// Package registry is the Lamplighter job registry.
//
// A chain has no timer: nothing on gno.land wakes a realm up. Lamplighter is
// the waking. A realm registers a callback, a schedule and a reward; once the
// job is due, anyone may call Exec, which runs the callback and pays the
// caller the reward in the same transaction.
//
// The callback is a crossing function value. The GnoVM runs it under the
// authority of the realm that declared it, wherever it is stored and whoever
// invokes it, so this registry can hold callbacks from any realm without
// gaining any power over their state.
package registry

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	// realmPath is this realm's package path, used to build links.
	realmPath = "gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry"

	// Denom is the only coin accepted as oil.
	Denom = "ugnot"

	// MinInterval is the shortest repeat interval, in seconds.
	MinInterval int64 = 10

	// MaxNameLen bounds the job name stored and rendered on chain.
	MaxNameLen = 80
)

// Job is one registered lamp: a callback, when it is next due, and the oil
// that pays whoever lights it.
type Job struct {
	id       uint64
	name     string
	owner    string // pkgpath of the realm that registered the job
	callback func(realm) error

	interval int64 // seconds between runs; 0 means the job runs once
	nextDue  int64 // unix time from which Exec is accepted

	reward  int64 // ugnot paid to the caller of each Exec
	balance int64 // ugnot held for this job

	runs     int64
	lastRun  int64
	lastBy   address
	finished bool // a one-shot job that has run
	closed   bool // cancelled by its owner
}

// Lighter is the running tally of one address that has executed jobs.
type Lighter struct {
	addr   address
	runs   int64
	earned int64
}

var (
	jobs     avl.Tree // zero-padded id -> *Job
	lighters avl.Tree // address -> *Lighter
	nextID   uint64   = 1

	// busy is the reentrancy lock held while a callback runs.
	busy bool

	totalRuns int64
	totalPaid int64
)

// Register adds a job and returns its id. Only a realm can register, and that
// realm becomes the job's owner.
//
// firstDue is the unix time of the first run; a value in the past means "as
// soon as possible". interval is the number of seconds between runs, or 0 for
// a job that runs once. reward is the ugnot paid to the caller of each Exec.
// The job holds no coins until someone calls Fund.
func Register(cur realm, name string, firstDue, interval, reward int64, callback func(realm) error) uint64 {
	prev := cur.Previous()
	if !prev.IsCode() {
		panic("only a realm can register a job")
	}
	if callback == nil {
		panic("callback must not be nil")
	}
	if name == "" || len(name) > MaxNameLen {
		panic("name must be 1 to " + strconv.Itoa(MaxNameLen) + " bytes")
	}
	if interval != 0 && interval < MinInterval {
		panic("interval must be 0 or at least " + strconv.FormatInt(MinInterval, 10) + " seconds")
	}
	if reward <= 0 {
		panic("reward must be positive")
	}

	now := time.Now().Unix()
	if firstDue < now {
		firstDue = now
	}

	id := nextID
	nextID++
	jobs.Set(key(id), &Job{
		id:       id,
		name:     name,
		owner:    prev.PkgPath(),
		callback: callback,
		interval: interval,
		nextDue:  firstDue,
		reward:   reward,
	})

	chain.Emit("JobRegistered", "id", utoa(id), "owner", prev.PkgPath())
	return id
}

// Fund adds the ugnot sent with the transaction to a job's balance. Anyone
// may fund any open job.
func Fund(cur realm, id uint64) {
	// OriginSend describes the transaction, not the immediate caller, so a
	// realm in between could otherwise claim someone else's coins as its own.
	runtime.AssertOriginCall()

	amount := deposit(id, unsafe.OriginSend())
	chain.Emit("JobFunded", "id", utoa(id), "amount", itoa(amount))
}

// deposit credits coins that have arrived with the transaction to a job and
// returns the amount credited.
func deposit(id uint64, sent chain.Coins) int64 {
	j := mustJob(id)
	if j.closed || j.finished {
		panic("job is no longer open")
	}
	amount := sent.AmountOf(Denom)
	if len(sent) != 1 || amount <= 0 {
		panic("send only " + Denom)
	}
	j.balance += amount
	return amount
}

// Exec runs a due job and pays its reward to the caller.
//
// A callback that returns an error or panics aborts the whole transaction, so
// a failing job pays nothing and changes nothing. Simulate before sending.
func Exec(cur realm, id uint64) {
	if busy {
		panic("reentrant call")
	}
	j := mustJob(id)
	if reason := notRunnable(j, time.Now().Unix()); reason != "" {
		panic(reason)
	}

	caller := cur.Previous().Address()
	now := time.Now().Unix()

	// Effects first: the job is already rescheduled and charged when the
	// callback runs, so nothing the callback does can run it twice.
	j.balance -= j.reward
	j.runs++
	j.lastRun = now
	j.lastBy = caller
	if j.interval == 0 {
		j.finished = true
	} else {
		j.nextDue = nextSlot(j.nextDue, j.interval, now)
	}

	busy = true
	if err := j.callback(cross(cur)); err != nil {
		panic("job failed: " + err.Error())
	}
	busy = false

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.Coins{{Denom, j.reward}})

	credit(caller, j.reward)
	totalRuns++
	totalPaid += j.reward

	chain.Emit("JobExecuted", "id", utoa(id), "by", caller.String(), "reward", itoa(j.reward))
}

// Cancel closes a job and sends its remaining balance to refundTo. Only the
// realm that registered the job may cancel it.
func Cancel(cur realm, id uint64, refundTo address) {
	if busy {
		panic("reentrant call")
	}
	j := mustJob(id)
	if cur.Previous().PkgPath() != j.owner {
		panic("only the owner realm can cancel a job")
	}
	if j.closed {
		panic("job is already closed")
	}
	if !refundTo.IsValid() {
		panic("invalid refund address")
	}

	refund := j.balance
	j.balance = 0
	j.closed = true
	j.callback = nil

	if refund > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), refundTo, chain.Coins{{Denom, refund}})
	}

	chain.Emit("JobCancelled", "id", utoa(id), "refund", itoa(refund))
}

// IsDue reports whether Exec would currently be accepted for a job.
func IsDue(id uint64) bool {
	j, ok := jobs.Get(key(id)).(*Job)
	if !ok {
		return false
	}
	return notRunnable(j, time.Now().Unix()) == ""
}

// DueJobs returns the ids of every job Exec would currently accept, comma
// separated. It is what an executor bot polls.
func DueJobs() string {
	now := time.Now().Unix()
	out := ""
	jobs.Iterate("", "", func(_ string, v any) bool {
		j := v.(*Job)
		if notRunnable(j, now) == "" {
			if out != "" {
				out += ","
			}
			out += utoa(j.id)
		}
		return false
	})
	return out
}

// notRunnable returns why a job cannot run at the given time, or "" if it can.
func notRunnable(j *Job, now int64) string {
	switch {
	case j.closed:
		return "job is closed"
	case j.finished:
		return "job has already run"
	case now < j.nextDue:
		return "job is not due yet"
	case j.balance < j.reward:
		return "job is out of oil"
	}
	return ""
}

// nextSlot returns the first slot after now on the grid due, due+interval,
// due+2*interval, and so on. Slots missed while nobody executed the job are
// skipped rather than replayed, and the grid never drifts.
func nextSlot(due, interval, now int64) int64 {
	if now < due {
		return due + interval
	}
	missed := (now - due) / interval
	return due + (missed+1)*interval
}

func credit(addr address, amount int64) {
	k := addr.String()
	l, ok := lighters.Get(k).(*Lighter)
	if !ok {
		lighters.Set(k, &Lighter{addr: addr, runs: 1, earned: amount})
		return
	}
	l.runs++
	l.earned += amount
}

func mustJob(id uint64) *Job {
	j, ok := jobs.Get(key(id)).(*Job)
	if !ok {
		panic("unknown job " + utoa(id))
	}
	return j
}

// key zero-pads the id so the tree iterates in numeric order.
func key(id uint64) string {
	s := utoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func utoa(n uint64) string { return strconv.FormatUint(n, 10) }
func itoa(n int64) string  { return strconv.FormatInt(n, 10) }

package registry

import (
	"chain"
	"chain/banker"
	"errors"
	"strings"
	"testing"
	"time"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const consumerPath = "gno.land/r/test/consumer"

var (
	registryAddr = chain.PackageAddress(realmPath)
	alice        = testutils.TestAddress("alice")
	bob          = testutils.TestAddress("bob")
)

// oil prepares a user sending ugnot along with a Fund call. The test banker
// does not move OriginSend coins by itself, so they are issued to the realm.
// Fund itself has to be called straight from the test function: the test
// runtime decides what an origin call is by counting call frames.
func oil(from address, amount int64) {
	coins := chain.Coins{{Denom, amount}}
	testing.IssueCoins(registryAddr, coins)
	testing.SetRealm(testing.NewUserRealm(from))
	testing.SetOriginSend(coins)
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, Denom)
}

func TestRegisterOnlyFromRealm(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "only a realm can register a job", func() {
		Register(cross(cur), "x", 0, 60, 1000, func(realm) error { return nil })
	})
}

func TestRegisterValidation(cur realm, t *testing.T) {
	ok := func(realm) error { return nil }
	testing.SetRealm(testing.NewCodeRealm(consumerPath))

	uassert.AbortsWithMessage(t, cur, "callback must not be nil", func() {
		Register(cross(cur), "x", 0, 60, 1000, nil)
	})
	uassert.AbortsWithMessage(t, cur, "name must be 1 to 80 bytes", func() {
		Register(cross(cur), "", 0, 60, 1000, ok)
	})
	uassert.AbortsWithMessage(t, cur, "interval must be 0 or at least 10 seconds", func() {
		Register(cross(cur), "x", 0, 5, 1000, ok)
	})
	uassert.AbortsWithMessage(t, cur, "reward must be positive", func() {
		Register(cross(cur), "x", 0, 60, 0, ok)
	})
}

func TestRepeatingJob(cur realm, t *testing.T) {
	ticks := 0
	start := time.Now().Unix()

	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "repeat", start+60, 60, 1000, func(realm) error {
		ticks++
		return nil
	})
	uassert.Equal(t, consumerPath, mustJob(id).owner)

	oil(alice, 2500)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)
	uassert.Equal(t, int64(2500), mustJob(id).balance)

	// Funded but not due.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.False(t, IsDue(id))
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() { Exec(cross(cur), id) })

	// 13 blocks of 5s: 65s later, 5s into the first slot.
	testing.SkipHeights(13)
	uassert.True(t, IsDue(id))
	uassert.True(t, strings.Contains(","+DueJobs()+",", ","+utoa(id)+","))

	before := balanceOf(bob)
	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), id)

	uassert.Equal(t, 1, ticks)
	uassert.Equal(t, before+1000, balanceOf(bob))
	j := mustJob(id)
	uassert.Equal(t, int64(1500), j.balance)
	uassert.Equal(t, int64(1), j.runs)
	uassert.Equal(t, bob, j.lastBy)
	// The grid holds: the next slot is start+120, not "now + 60".
	uassert.Equal(t, start+120, j.nextDue)

	// The same slot cannot be run twice.
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() { Exec(cross(cur), id) })

	// Three slots pass with nobody running the job: it runs once, not three times.
	testing.SkipHeights(36) // +180s, now start+245
	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), id)
	uassert.Equal(t, 2, ticks)
	uassert.Equal(t, start+300, mustJob(id).nextDue)

	// 500 ugnot left cannot pay a 1000 ugnot reward.
	testing.SkipHeights(24)
	uassert.False(t, IsDue(id))
	uassert.AbortsWithMessage(t, cur, "job is out of oil", func() { Exec(cross(cur), id) })

	l, ok := lighters.Get(bob.String()).(*Lighter)
	uassert.True(t, ok)
	uassert.Equal(t, int64(2), l.runs)
	uassert.Equal(t, int64(2000), l.earned)
}

func TestOneShotJob(cur realm, t *testing.T) {
	fired := 0
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "once", 0, 0, 700, func(realm) error {
		fired++
		return nil
	})
	oil(alice, 700)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), id)
	uassert.Equal(t, 1, fired)
	uassert.True(t, mustJob(id).finished)

	uassert.AbortsWithMessage(t, cur, "job has already run", func() { Exec(cross(cur), id) })
	uassert.PanicsWithMessage(t, cur, "job is no longer open", func() {
		deposit(id, chain.Coins{{Denom, 1}})
	})
}

func TestFailingCallbackAborts(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "broken", 0, 60, 1000, func(realm) error {
		return errors.New("tap is jammed")
	})
	oil(alice, 5000)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "job failed: tap is jammed", func() { Exec(cross(cur), id) })

	// On chain the abort reverts the whole transaction. The test runtime
	// keeps the half-applied state, so undo the lock by hand.
	busy = false
}

func TestCallbackSeesRegistryAsCaller(cur realm, t *testing.T) {
	seen := ""
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "who calls", 0, 60, 1000, func(cur realm) error {
		seen = cur.Previous().PkgPath()
		return nil
	})
	oil(alice, 1000)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), id)
	uassert.Equal(t, realmPath, seen)
}

// The refusals are tested on deposit, the part of Fund after the origin-call
// check: the test runtime only treats a call made straight from the test
// function as an origin call, which rules out wrapping Fund in an assertion.
func TestFundRejectsOtherCoins(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "fund me", 0, 60, 1000, func(realm) error { return nil })

	uassert.PanicsWithMessage(t, cur, "send only ugnot", func() {
		deposit(id, chain.Coins{{"other", 5}})
	})
	uassert.PanicsWithMessage(t, cur, "send only ugnot", func() {
		deposit(id, chain.Coins{{Denom, 5}, {"other", 5}})
	})
	uassert.PanicsWithMessage(t, cur, "send only ugnot", func() { deposit(id, nil) })
	uassert.PanicsWithMessage(t, cur, "unknown job 999999", func() {
		deposit(999999, chain.Coins{{Denom, 5}})
	})
	uassert.Equal(t, int64(0), mustJob(id).balance)
}

func TestCancel(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "cancel me", 0, 60, 1000, func(realm) error { return nil })
	oil(alice, 3000)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	// A user, and another realm, are both refused.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "only the owner realm can cancel a job", func() {
		Cancel(cross(cur), id, bob)
	})
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/other"))
	uassert.AbortsWithMessage(t, cur, "only the owner realm can cancel a job", func() {
		Cancel(cross(cur), id, bob)
	})

	before := balanceOf(alice)
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	Cancel(cross(cur), id, alice)
	uassert.Equal(t, before+3000, balanceOf(alice))
	uassert.True(t, mustJob(id).closed)
	uassert.False(t, IsDue(id))

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "job is closed", func() { Exec(cross(cur), id) })
}

func TestNextSlot(t *testing.T) {
	cases := []struct {
		due, interval, now, want int64
	}{
		{100, 60, 100, 160}, // run exactly on time
		{100, 60, 159, 160}, // run late within the slot
		{100, 60, 160, 220}, // run exactly one slot late
		{100, 60, 400, 460}, // five slots missed: skip them
		{100, 60, 50, 160},  // defensive: run before due
	}
	for _, c := range cases {
		uassert.Equal(t, c.want, nextSlot(c.due, c.interval, c.now))
	}
}

func TestFormatting(t *testing.T) {
	uassert.Equal(t, "0 GNOT", gnot(0))
	uassert.Equal(t, "1 GNOT", gnot(1000000))
	uassert.Equal(t, "0.1 GNOT", gnot(100000))
	uassert.Equal(t, "2.000001 GNOT", gnot(2000001))
	uassert.Equal(t, "0s", span(0))
	uassert.Equal(t, "30s", span(30))
	uassert.Equal(t, "1m30s", span(90))
	uassert.Equal(t, "1h", span(3600))
	uassert.Equal(t, "1d1h", span(90061))
	uassert.Equal(t, "a/b (c)", cell("a|b [c]"))
}

func TestRender(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	id := Register(cross(cur), "render | me", 0, 3600, 1000, func(realm) error { return nil })
	oil(alice, 1000)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	home := Render("")
	uassert.True(t, strings.Contains(home, "# Lamplighter"))
	uassert.True(t, strings.Contains(home, "render / me"))
	uassert.True(t, strings.Contains(home, "**due now**"))

	page := Render("job/" + utoa(id))
	uassert.True(t, strings.Contains(page, "`"+consumerPath+"`"))
	uassert.True(t, strings.Contains(page, "Run it now"))

	uassert.True(t, strings.Contains(Render("job/999999"), "404"))
	uassert.True(t, strings.Contains(Render("nope"), "404"))
}

package registry

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
)

// Render serves the dashboard:
//
//	""        every job, then the lighters
//	"job/<id>" one job in detail
func Render(path string) string {
	if strings.HasPrefix(path, "job/") {
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "job/"), 10, 64)
		if err != nil {
			return "# 404\n\nNot a job id."
		}
		return renderJob(id)
	}
	if path != "" {
		return "# 404\n\nNothing here."
	}
	return renderHome()
}

func renderHome() string {
	now := time.Now().Unix()
	var b strings.Builder

	b.WriteString("# Lamplighter\n\n")
	b.WriteString("Nothing on gno.land wakes a realm up. Here, realms post the work they need done on a schedule, ")
	b.WriteString("and anyone who runs a due job is paid its reward in the same transaction.\n\n")
	b.WriteString("**" + itoa(int64(jobs.Size())) + "** jobs · **" + itoa(totalRuns) + "** runs · **" + gnot(totalPaid) + "** paid out\n\n")

	b.WriteString("## Jobs\n\n")
	if jobs.Size() == 0 {
		b.WriteString("No jobs yet. A realm registers one by calling `Register`.\n\n")
	} else {
		b.WriteString("| # | Job | Owner | Every | Status | Reward | Oil | Runs | |\n")
		b.WriteString("|---|---|---|---|---|---|---|---|---|\n")
		jobs.Iterate("", "", func(_ string, v any) bool {
			j := v.(*Job)
			action := ""
			if notRunnable(j, now) == "" {
				action = "[Run it](" + txlink.Call("Exec", "id", utoa(j.id)) + ")"
			}
			b.WriteString("| [" + utoa(j.id) + "](" + jobPath(j.id) + ") | " + cell(j.name) +
				" | " + shortPath(j.owner) +
				" | " + every(j.interval) +
				" | " + status(j, now) +
				" | " + gnot(j.reward) +
				" | " + gnot(j.balance) +
				" | " + itoa(j.runs) +
				" | " + action + " |\n")
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## Lamplighters\n\n")
	if lighters.Size() == 0 {
		b.WriteString("Nobody has run a job yet.\n")
	} else {
		b.WriteString("| Address | Runs | Earned |\n|---|---|---|\n")
		lighters.Iterate("", "", func(_ string, v any) bool {
			l := v.(*Lighter)
			b.WriteString("| " + l.addr.String() + " | " + itoa(l.runs) + " | " + gnot(l.earned) + " |\n")
			return false
		})
	}
	return b.String()
}

func renderJob(id uint64) string {
	j, ok := jobs.Get(key(id)).(*Job)
	if !ok {
		return "# 404\n\nNo job " + utoa(id) + "."
	}
	now := time.Now().Unix()

	var b strings.Builder
	b.WriteString("# Job " + utoa(j.id) + ": " + cell(j.name) + "\n\n")
	b.WriteString("- **Owner:** `" + j.owner + "`\n")
	b.WriteString("- **Status:** " + status(j, now) + "\n")
	b.WriteString("- **Schedule:** " + every(j.interval) + "\n")
	if !j.closed && !j.finished {
		b.WriteString("- **Next due:** " + time.Unix(j.nextDue, 0).UTC().Format(time.RFC3339) + "\n")
	}
	b.WriteString("- **Reward per run:** " + gnot(j.reward) + "\n")
	b.WriteString("- **Oil left:** " + gnot(j.balance))
	if j.reward > 0 {
		b.WriteString(" (" + itoa(j.balance/j.reward) + " runs)")
	}
	b.WriteString("\n")
	b.WriteString("- **Runs so far:** " + itoa(j.runs) + "\n")
	if j.runs > 0 {
		b.WriteString("- **Last run:** " + time.Unix(j.lastRun, 0).UTC().Format(time.RFC3339) + " by " + j.lastBy.String() + "\n")
	}
	b.WriteString("\n")

	if notRunnable(j, now) == "" {
		b.WriteString("[Run it now](" + txlink.Call("Exec", "id", utoa(j.id)) + ") · ")
	}
	if !j.closed && !j.finished {
		b.WriteString("[Add oil](" + txlink.NewLink("Fund").AddArgs("id", utoa(j.id)).SetSend("1000000"+Denom).URL() + ") · ")
	}
	b.WriteString("[All jobs](" + homePath() + ")\n")
	return b.String()
}

// status is the one-phrase state of a job at the given time.
func status(j *Job, now int64) string {
	switch {
	case j.closed:
		return "closed"
	case j.finished:
		return "done"
	case j.balance < j.reward:
		return "out of oil"
	case now >= j.nextDue:
		return "**due now**"
	}
	return "in " + span(j.nextDue-now)
}

func every(interval int64) string {
	if interval == 0 {
		return "once"
	}
	return span(interval)
}

// span renders a duration in seconds using its two largest units.
func span(s int64) string {
	units := []struct {
		n    int64
		name string
	}{{86400, "d"}, {3600, "h"}, {60, "m"}, {1, "s"}}

	out := ""
	parts := 0
	for _, u := range units {
		if s >= u.n && parts < 2 {
			out += itoa(s/u.n) + u.name
			s %= u.n
			parts++
		}
	}
	if out == "" {
		return "0s"
	}
	return out
}

// gnot renders an ugnot amount as GNOT with up to six decimals.
func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := itoa(frac)
	for len(f) < 6 {
		f = "0" + f
	}
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

// cell makes a user-supplied string safe inside a markdown table cell.
func cell(s string) string {
	s = strings.ReplaceAll(s, "|", "/")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "[", "(")
	s = strings.ReplaceAll(s, "]", ")")
	s = strings.ReplaceAll(s, "<", "(")
	s = strings.ReplaceAll(s, ">", ")")
	return s
}

func shortPath(pkgPath string) string {
	return "`" + strings.TrimPrefix(pkgPath, "gno.land") + "`"
}

func homePath() string {
	return strings.TrimPrefix(realmPath, "gno.land")
}

func jobPath(id uint64) string {
	return homePath() + ":job/" + utoa(id)
}

// Package taproom is a small realm that needs waking: the brew on tap changes
// on a schedule, and nothing in the realm can make that happen by itself.
//
// It registers one Lamplighter job when it is deployed. Whoever runs that job
// rotates the tap and is paid by the registry.
package taproom

import (
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry"
)

const (
	registryPath = "gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry"

	// rotateEvery is the number of seconds each brew stays on tap.
	rotateEvery int64 = 300

	// reward is the ugnot the registry pays for each rotation.
	reward int64 = 50000
)

var (
	brews = []string{
		"Gnomish Amber",
		"Deep Root Stout",
		"Mushroom Mead",
		"Lantern Lager",
		"Tinker's Pale",
	}

	onTap     int
	rotations int64
	since     int64
	jobID     uint64
)

func init(cur realm) {
	since = time.Now().Unix()
	jobID = registry.Register(cross(cur), "Taproom: change the brew on tap",
		since+rotateEvery, rotateEvery, reward, rotate)
}

// rotate is the callback the registry holds. It is unexported and gated on
// the registry being the caller, so the schedule is the only way to reach it.
func rotate(cur realm) error {
	if cur.Previous().PkgPath() != registryPath {
		return errors.New("only the lamplighter registry may rotate the tap")
	}
	onTap = (onTap + 1) % len(brews)
	rotations++
	since = time.Now().Unix()
	return nil
}

// OnTap returns the brew currently on tap.
func OnTap() string { return brews[onTap] }

// Rotations returns how many times the tap has been changed.
func Rotations() int64 { return rotations }

// JobID returns the id of this realm's job in the registry.
func JobID() uint64 { return jobID }

func Render(_ string) string {
	job := strconv.FormatUint(jobID, 10)
	registryURL := strings.TrimPrefix(registryPath, "gno.land")

	var b strings.Builder
	b.WriteString("# The Taproom\n\n")
	b.WriteString("## On tap: " + OnTap() + "\n\n")
	b.WriteString("Poured since " + time.Unix(since, 0).UTC().Format(time.RFC3339) +
		". The tap has been changed " + strconv.FormatInt(rotations, 10) + " times.\n\n")
	b.WriteString("The brew changes every " + strconv.FormatInt(rotateEvery/60, 10) +
		" minutes, but this realm cannot wake itself. It posted the work as [Lamplighter job " +
		job + "](" + registryURL + ":job/" + job + "): whoever runs it changes the tap and is paid for it.\n\n")
	b.WriteString("| Brew | |\n|---|---|\n")
	for i, name := range brews {
		mark := ""
		if i == onTap {
			mark = "on tap"
		}
		b.WriteString("| " + name + " | " + mark + " |\n")
	}
	return b.String()
}

