func TestRender(cur realm, t *testing.T) {
	// A name made to look like a status, a link and a table break.
	id := post(cur, "**due now** [x](http://evil) | row", 0, 3600, 1000, nop)
	testing.SetRealm(testing.NewUserRealm(alice))
	oil(1000)
	Fund(cross(cur), id)
	testing.SetOriginSend(nil)

	home := Render("")
	uassert.True(t, strings.Contains(home, "# Lamplighter"))
	uassert.True(t, strings.Contains(home, "## Post a job from your realm"))
	uassert.True(t, strings.Contains(home, `import "`+wantPath+`"`))
	uassert.False(t, strings.Contains(home, "(http://evil)"), "a name cannot plant a link")
	uassert.False(t, strings.Contains(home, "[**due now** "), "a name cannot fake a status")

	prefix := "/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
	page := Render("job/" + utoa(id))
	uassert.True(t, strings.Contains(page, "**Status:** **due now**"))
	uassert.True(t, strings.Contains(page, "("+prefix+"$help&func=Exec&id="+utoa(id)+")"), "the run link names this realm")
	uassert.True(t, strings.Contains(page, prefix+"$help&func=Fund&"), "the fund link names this realm")
	uassert.True(t, strings.Contains(page, "-max-deposit 10000ugnot"))
	uassert.True(t, strings.Contains(page, "[/r/test/consumer](/r/test/consumer)"))

	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), id)
	uassert.True(t, strings.Contains(Render(""), "| "+bob.String()+" | 0.001 GNOT |"))
	uassert.True(t, strings.Contains(Render("job/"+utoa(id)), "**Last run:**"))

	once := post(cur, "gone soon", 0, 0, 1000, nop)
	// The fund link of a job that runs once offers exactly what it still needs.
	uassert.True(t, strings.Contains(Render("job/"+utoa(once)), ".send=1000ugnot"))
	testing.IssueCoins(registryAddr, chain.Coins{{Denom, 1000}})
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	Credit(cross(cur), once, 1000)
	uassert.True(t, strings.Contains(Render("job/"+utoa(once)), "already holds its reward"))
	uassert.False(t, strings.Contains(Render("job/"+utoa(once)), "func=Fund"))
	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), once)
	uassert.True(t, strings.Contains(Render("job/"+utoa(once)), "ran once and is done"))
	uassert.True(t, strings.Contains(Render(""), "| done |"))
	testing.SetRealm(testing.NewCodeRealm(consumerPath))
	Cancel(cross(cur), once, alice)
	uassert.True(t, strings.Contains(Render("job/"+utoa(once)), "This job was cancelled"))

	uassert.True(t, strings.Contains(Render("job/999999"), "# 404"))
	uassert.True(t, strings.Contains(Render("job/abc"), "# 404"))
	uassert.True(t, strings.Contains(Render("page/0"), "# 404"))
	uassert.True(t, strings.Contains(Render("nope"), "# 404"))
}

func TestRenderPages(cur realm, t *testing.T) {
	for jobs.Size() <= 2*pageSize {
		post(cur, "filler", 0, 3600, 1000, nop)
	}
	first := Render("")
	uassert.True(t, strings.Contains(first, "Page 1 of 3"))
	uassert.True(t, strings.Contains(first, ":page/2)"))
	uassert.False(t, strings.Contains(first, "previous"))

	last := Render("page/3")
	uassert.True(t, strings.Contains(last, "Page 3 of 3"))
	uassert.True(t, strings.Contains(last, "previous"))
	uassert.False(t, strings.Contains(last, "[next]"))
	// A full page lists exactly pageSize jobs, each with two links to its page.
	table, _, _ := strings.Cut(first, "## Recent runs")
	uassert.Equal(t, 2*pageSize, strings.Count(table, ":job/"))

	uassert.True(t, strings.Contains(Render("page/99"), "No such page"))
}

package registry

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// pageSize is how many jobs one page of the dashboard lists.
const pageSize = 20

// execDeposit is the storage deposit limit the dashboard suggests for running
// a job: enough for a callback that updates its own state, far too little for
// one that tries to grow state at the runner's expense.
const execDeposit = "10000" + Denom

// Render serves the dashboard:
//
//	""         the first page of open jobs, recent runs, and how to take part
//	"page/<n>" a later page of open jobs
//	"job/<id>" one job in detail
func Render(path string) string {
	switch {
	case path == "":
		return renderHome(1)
	case strings.HasPrefix(path, "page/"):
		n, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || n < 1 {
			return "# 404\n\nNot a page number."
		}
		return renderHome(n)
	case strings.HasPrefix(path, "job/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "job/"), 10, 64)
		if err != nil {
			return "# 404\n\nNot a job id."
		}
		return renderJob(id)
	}
	return "# 404\n\nNothing here."
}

func renderHome(page int) string {
	now := time.Now().Unix()
	var b strings.Builder

	b.WriteString("# Lamplighter\n\n")
	b.WriteString("gno.land has no scheduler: a realm only runs when a transaction calls it. ")
	b.WriteString("This is where realms post work that has to happen on a schedule. ")
	b.WriteString("Anyone who runs a job once it is due is paid its reward in the same transaction.\n\n")
	b.WriteString("**" + plural(int64(jobs.Size()), "job") + "** · **" + plural(totalRuns, "run") +
		"** · **" + gnot(totalPaid) + "** paid out\n\n")

	b.WriteString("## Jobs\n\n")
	pages := (jobs.Size() + pageSize - 1) / pageSize
	switch {
	case jobs.Size() == 0:
		b.WriteString("No jobs. A realm posts one by calling `Register`; see the end of this page.\n\n")
	case page > pages:
		b.WriteString("No such page. [First page](" + homePath() + ")\n\n")
	default:
		b.WriteString("| # | Job | Posted by | Every | Next run | Reward | Oil | Runs |\n")
		b.WriteString("|---|---|---|---|---|---|---|---|\n")
		jobs.IterateByOffset((page-1)*pageSize, pageSize, func(_ string, v any) bool {
			j := v.(*job)
			b.WriteString("| [" + utoa(j.id) + "](" + jobPath(j.id) + ")" +
				" | [" + sanitize.TableCell(j.name) + "](" + jobPath(j.id) + ")" +
				" | " + realmLink(j.owner) +
				" | " + every(j.interval) +
				" | " + status(j, now) +
				" | " + gnot(j.reward) +
				" | " + gnot(j.balance) +
				" | " + itoa(j.runs) + " |\n")
			return false
		})
		b.WriteString("\n")
		if pages > 1 {
			b.WriteString("Page " + strconv.Itoa(page) + " of " + strconv.Itoa(pages))
			if page > 1 {
				b.WriteString(" · [previous](" + pagePath(page-1) + ")")
			}
			if page < pages {
				b.WriteString(" · [next](" + pagePath(page+1) + ")")
			}
			b.WriteString("\n\n")
		}
	}

	b.WriteString("## Recent runs\n\n")
	runs := recentRuns()
	if len(runs) == 0 {
		b.WriteString("Nobody has run a job yet.\n\n")
	} else {
		b.WriteString("| When | Job | Run by | Paid |\n|---|---|---|---|\n")
		for _, r := range runs {
			b.WriteString("| " + clock(r.at) +
				" | [" + utoa(r.job) + "](" + jobPath(r.job) + ")" +
				" | " + r.by.String() +
				" | " + gnot(r.reward) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Run jobs and get paid\n\n")
	b.WriteString("Open a job marked **due now** and run it: the reward lands in your account in the same transaction. ")
	b.WriteString("A bot can do it for you: it polls `DueJobs`, simulates each run, and only sends the ones that pay more than they cost.\n\n")
	b.WriteString("Running a job executes code written by the realm that posted it, and you pay the storage deposit for any state that code adds. ")
	b.WriteString("Always set a low limit, such as `-max-deposit " + execDeposit + "`, so that a hostile job cannot spend your coins on its own storage.\n\n")

	b.WriteString("## Post a job from your realm\n\n")
	b.WriteString("Register a callback when your realm is deployed, then fund the job. The callback must check that this realm is the caller and that the job is its own:\n\n")
	b.WriteString("```go\n")
	b.WriteString("import \"" + realmPath + "\"\n\n")
	b.WriteString("var job uint64\n\n")
	b.WriteString("func init(cur realm) {\n")
	b.WriteString("\t// first run in an hour, then every hour, paying 0.05 GNOT a run\n")
	b.WriteString("\tjob = registry.Register(cross(cur), \"Hourly settlement\",\n")
	b.WriteString("\t\ttime.Now().Unix()+3600, 3600, 50000, settle)\n")
	b.WriteString("}\n\n")
	b.WriteString("func settle(cur realm, id uint64) error {\n")
	b.WriteString("\tif cur.Previous().PkgPath() != registry.Path() || id != job {\n")
	b.WriteString("\t\treturn errors.New(\"not my job\")\n")
	b.WriteString("\t}\n")
	b.WriteString("\t// ... the work ...\n")
	b.WriteString("\treturn nil\n")
	b.WriteString("}\n")
	b.WriteString("```\n\n")
	b.WriteString("Anyone can add oil with `Fund`. A realm sends coins here and calls `Credit` for the same amount. ")
	b.WriteString("Oil belongs to the job: only the realm that posted it can `Cancel` it and say where the remainder goes.\n\n")
	b.WriteString("Posting a job locks a storage deposit for its state, from whoever sends that transaction. ")
	b.WriteString("Only `Cancel` removes a job, and the deposit is released to whoever sends that transaction, so cancel a job once it is done.\n")
	return b.String()
}

func renderJob(id uint64) string {
	j, ok := jobs.Get(key(id)).(*job)
	if !ok {
		if id > 0 && id < nextID {
			return "# Job " + utoa(id) + "\n\nThis job was cancelled.\n\n[All jobs](" + homePath() + ")\n"
		}
		return "# 404\n\nNo job " + utoa(id) + ".\n\n[All jobs](" + homePath() + ")\n"
	}
	now := time.Now().Unix()
	this := txlink.Realm(realmPath)

	var b strings.Builder
	b.WriteString("# Job " + utoa(j.id) + ": " + sanitize.InlineText(j.name) + "\n\n")
	b.WriteString("- **Posted by:** " + realmLink(j.owner) + "\n")
	b.WriteString("- **Status:** " + status(j, now) + "\n")
	b.WriteString("- **Schedule:** " + every(j.interval) + "\n")
	if !j.done {
		b.WriteString("- **Next run:** " + clock(j.nextDue) + "\n")
	}
	b.WriteString("- **Reward per run:** " + gnot(j.reward) + "\n")
	b.WriteString("- **Oil left:** " + gnot(j.balance) + " (" + plural(j.balance/j.reward, "run") + ")\n")
	b.WriteString("- **Runs so far:** " + itoa(j.runs) + "\n")
	if j.runs > 0 {
		b.WriteString("- **Last run:** " + clock(j.lastRun) + " by " + j.lastBy.String() + "\n")
	}
	b.WriteString("\n")

	if j.done {
		b.WriteString("This job ran once and is done. Its owner can cancel it to free its state.\n\n")
		b.WriteString("[All jobs](" + homePath() + ")\n")
		return b.String()
	}

	b.WriteString("## Run it\n\n")
	if notRunnable(j, now) == "" {
		b.WriteString("This job is due. [Run it and collect " + gnot(j.reward) + "](" + this.Call("Exec", "id", utoa(j.id)) + ")\n\n")
	} else {
		b.WriteString("This job cannot run right now: " + notRunnable(j, now) + ".\n\n")
	}
	b.WriteString("Running it executes code written by " + realmLink(j.owner) + ", and you pay the storage deposit for any state that code adds. ")
	b.WriteString("Add `-max-deposit " + execDeposit + "` to the command.\n\n")

	b.WriteString("## Add oil\n\n")
	switch {
	case j.interval != 0:
		b.WriteString("[Fund this job with 1 GNOT](" + this.NewLink("Fund").AddArgs("id", utoa(j.id)).SetSend("1000000"+Denom).URL() + ")\n\n")
	case j.balance < j.reward:
		// A job that runs once holds exactly one reward.
		need := j.reward - j.balance
		b.WriteString("[Fund this job with the " + gnot(need) + " it needs](" + this.NewLink("Fund").AddArgs("id", utoa(j.id)).SetSend(itoa(need)+Denom).URL() + ")\n\n")
	default:
		b.WriteString("This job runs once and already holds its reward.\n\n")
	}
	b.WriteString("Oil belongs to the job. Only the realm that posted it can cancel it, and that realm decides where the remainder goes.\n\n")
	b.WriteString("[All jobs](" + homePath() + ")\n")
	return b.String()
}

// status is the one-phrase state of a job at the given time.
func status(j *job, now int64) string {
	switch {
	case j.done:
		return "done"
	case j.balance < j.reward:
		return "out of oil"
	case now >= j.nextDue:
		return "**due now**"
	}
	return "in " + span(j.nextDue-now)
}

func every(interval int64) string {
	if interval == 0 {
		return "once"
	}
	return span(interval)
}

// span renders a duration in seconds using its two largest units.
func span(s int64) string {
	units := []struct {
		n    int64
		name string
	}{{86400, "d"}, {3600, "h"}, {60, "m"}, {1, "s"}}

	out := ""
	parts := 0
	for _, u := range units {
		if s >= u.n && parts < 2 {
			out += itoa(s/u.n) + u.name
			s %= u.n
			parts++
		}
	}
	if out == "" {
		return "0s"
	}
	return out
}

// clock renders a unix time as UTC.
func clock(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04:05") + " UTC"
}

// gnot renders an ugnot amount as GNOT with up to six decimals.
func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := pad(itoa(frac), 6)
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

// plural renders a count with its noun: "1 run", "2 runs".
func plural(n int64, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	return itoa(n) + " " + noun + "s"
}

// realmLink links to a realm, showing its path with any address shortened.
// The path comes from the chain, never from a user, so it needs no escaping.
func realmLink(pkgPath string) string {
	path := strings.TrimPrefix(pkgPath, "gno.land")
	parts := strings.Split(path, "/")
	for i, p := range parts {
		if len(p) == 40 && strings.HasPrefix(p, "g1") {
			parts[i] = p[:6] + "…" + p[len(p)-4:]
		}
	}
	return "[" + strings.Join(parts, "/") + "](" + path + ")"
}

func homePath() string {
	return strings.TrimPrefix(realmPath, "gno.land")
}

func jobPath(id uint64) string {
	return homePath() + ":job/" + utoa(id)
}

func pagePath(n int) string {
	if n <= 1 {
		return homePath()
	}
	return homePath() + ":page/" + strconv.Itoa(n)
}

package registry

import (
	"time"
)

// Exists reports whether a job is registered and has not been cancelled. A
// job that runs once still exists after its run, until its owner cancels it.
func Exists(id uint64) bool {
	return jobs.Has(key(id))
}

// Done reports whether a job that runs once has had its run.
func Done(id uint64) bool {
	j, ok := jobs.Get(key(id)).(*job)
	return ok && j.done
}

// IsDue reports whether Exec would currently be accepted for a job.
func IsDue(id uint64) bool {
	j, ok := jobs.Get(key(id)).(*job)
	return ok && notRunnable(j, time.Now().Unix()) == ""
}

// NextDue returns the unix time from which a job's next run is accepted, or
// 0 if the job does not exist.
func NextDue(id uint64) int64 {
	if j, ok := jobs.Get(key(id)).(*job); ok {
		return j.nextDue
	}
	return 0
}

// Balance returns the ugnot a job holds, or 0 if the job does not exist.
func Balance(id uint64) int64 {
	if j, ok := jobs.Get(key(id)).(*job); ok {
		return j.balance
	}
	return 0
}

// Reward returns the ugnot a job pays per run, or 0 if the job does not exist.
func Reward(id uint64) int64 {
	if j, ok := jobs.Get(key(id)).(*job); ok {
		return j.reward
	}
	return 0
}

// Owner returns the package path of the realm that registered a job, or ""
// if the job does not exist.
func Owner(id uint64) string {
	if j, ok := jobs.Get(key(id)).(*job); ok {
		return j.owner
	}
	return ""
}

// DueJobs lists jobs Exec would currently accept, the longest overdue first,
// as comma-separated "id:reward:due" entries, at most limit of them (capped at
// MaxPage). It is what an executor polls.
//
// To read on from a full page, pass the due time and id of its last entry as
// afterDue and afterID; pass 0 and 0 for the first page. Paging by position
// rather than by count means a reader never pays again for the entries it has
// already seen, however many jobs sit at the head of the list.
//
// It reads the queue index, so its cost depends on how many jobs it returns,
// not on how many are registered.
func DueJobs(afterDue int64, afterID uint64, limit int) string {
	if limit <= 0 || limit > MaxPage {
		limit = MaxPage
	}

	start := ""
	if afterDue > 0 || afterID > 0 {
		if afterDue < 0 {
			afterDue = 0
		}
		start = dueKey(afterDue, afterID) + "0" // the smallest key above that entry's own
	}
	// Every due key below this one has nextDue <= now; parked jobs sort above it.
	end := dueKey(time.Now().Unix()+1, 0)

	out := ""
	taken := 0
	queue.Iterate(start, end, func(_ string, v any) bool {
		j := v.(*job)
		if out != "" {
			out += ","
		}
		out += utoa(j.id) + ":" + itoa(j.reward) + ":" + itoa(j.nextDue)
		taken++
		return taken >= limit
	})
	return out
}

// recentSize is how many past runs the registry remembers.
const recentSize = 8

// run is one past execution, kept for the dashboard.
type run struct {
	job    uint64
	by     address
	at     int64 // unix time; 0 marks a slot that has never been used
	reward int64
}

// recent is a ring of the last runs. Whoever sends a transaction pays a
// storage deposit for every byte of state it adds, so a table with one row
// per executor would charge each newcomer for their own row. The ring is
// allocated in full when the realm is deployed and a run overwrites a slot in
// place, so that recording a run does not grow the state by a row.
var (
	recent     [recentSize]run
	recentNext int
)

// initRecent fills every slot with an address, so that the first runs do not
// each grow the state by one.
func initRecent(placeholder address) {
	for i := range recent {
		recent[i].by = placeholder
	}
}

// remember records a run in the ring, overwriting the oldest one.
func remember(id uint64, by address, at, reward int64) {
	r := &recent[recentNext]
	r.job = id
	r.by = by
	r.at = at
	r.reward = reward
	recentNext = (recentNext + 1) % recentSize
}

// recentRuns returns the remembered runs, newest first.
func recentRuns() []run {
	out := make([]run, 0, recentSize)
	for i := 1; i <= recentSize; i++ {
		r := recent[(recentNext-i+recentSize)%recentSize]
		if r.at != 0 {
			out = append(out, r)
		}
	}
	return out
}

// Package taproom is a small realm that needs waking: the brew on tap changes
// on a schedule, and nothing in the realm can make that happen by itself.
//
// It posts one Lamplighter job when it is deployed. Whoever runs that job
// changes the tap and is paid by the registry.
package taproom

import (
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

const (
	// rotateEvery is the number of seconds each brew stays on tap.
	rotateEvery int64 = 300

	// reward is the ugnot the registry pays for each rotation.
	reward int64 = 50000
)

var (
	brews = []string{
		"Gnomish Amber",
		"Deep Root Stout",
		"Mushroom Mead",
		"Lantern Lager",
		"Tinker's Pale",
	}

	onTap     int
	rotations int64
	since     int64
	jobID     uint64

	// keeper is the account that deployed the taproom. It alone can close it.
	keeper address
	closed bool
)

func init(cur realm) {
	keeper = cur.Previous().Address()
	since = time.Now().Unix()
	jobID = registry.Register(cross(cur), "Taproom: change the brew on tap",
		since+rotateEvery, rotateEvery, reward, rotate)
}

// rotate is the callback the registry holds.
//
// The registry runs any callback for anyone, so "the registry called me" is
// not enough: another realm could post a job of its own that points here. The
// job id is what ties a call to the schedule this realm asked for.
func rotate(cur realm, job uint64) error {
	if cur.Previous().PkgPath() != registry.Path() || job != jobID {
		return errors.New("only the taproom's own lamplighter job may change the tap")
	}
	onTap = (onTap + 1) % len(brews)
	rotations++
	since = time.Now().Unix()
	return nil
}

// Close stops the rotation for good and returns the oil the job still holds
// to the keeper. Only the keeper can call it.
func Close(cur realm) {
	if cur.Previous().Address() != keeper {
		panic("only the keeper can close the taproom")
	}
	if closed {
		panic("the taproom is already closed")
	}
	closed = true
	registry.Cancel(cross(cur), jobID, keeper)
}

// OnTap returns the brew currently on tap.
func OnTap() string { return brews[onTap] }

// Rotations returns how many times the tap has been changed.
func Rotations() int64 { return rotations }

// JobID returns the id of this realm's job in the registry.
func JobID() uint64 { return jobID }

// Keeper returns the account that can close the taproom.
func Keeper() address { return keeper }

func Render(_ string) string {
	job := strconv.FormatUint(jobID, 10)
	registryURL := strings.TrimPrefix(registry.Path(), "gno.land")
	jobURL := registryURL + ":job/" + job
	now := time.Now().Unix()

	var b strings.Builder
	b.WriteString("# The Taproom\n\n")
	b.WriteString("## On tap: " + OnTap() + "\n\n")
	b.WriteString("Poured since " + time.Unix(since, 0).UTC().Format("2006-01-02 15:04:05") +
		" UTC. The tap has been changed " + strconv.FormatInt(rotations, 10) + " times.\n\n")

	if closed {
		b.WriteString("The taproom is closed: its keeper stopped the rotation.\n\n")
	} else {
		b.WriteString("The brew should change every " + strconv.FormatInt(rotateEvery/60, 10) +
			" minutes, but a realm cannot wake itself. So the taproom posted the work as [Lamplighter job " +
			job + "](" + jobURL + "): whoever runs it changes the tap and is paid " +
			strconv.FormatInt(reward, 10) + " ugnot for it.\n\n")

		switch {
		case registry.IsDue(jobID):
			b.WriteString("**The next change is due now.** [Run the job](" + jobURL + ") and it is yours.\n\n")
		case registry.Balance(jobID) < reward:
			b.WriteString("**The job is out of oil**, so nobody will change the tap. [Add oil](" +
				txlink.Realm(registry.Path()).NewLink("Fund").AddArgs("id", job).SetSend("1000000ugnot").URL() + ")\n\n")
		default:
			b.WriteString("Next change in " + strconv.FormatInt(registry.NextDue(jobID)-now, 10) + " seconds.\n\n")
		}
	}

	b.WriteString("| Brew | |\n|---|---|\n")
	for i, name := range brews {
		mark := ""
		if i == onTap {
			mark = "on tap"
		}
		b.WriteString("| " + name + " | " + mark + " |\n")
	}
	return b.String()
}

package taproom

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

var (
	registryAddr = chain.PackageAddress(registry.Path())
	patron       = testutils.TestAddress("patron")
	lighter      = testutils.TestAddress("lighter")
)

func ugnotOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, registry.Denom)
}

// restock gives the registry back the coins the taproom's job holds. The test
// runtime starts every test function with empty balances but keeps realm
// state, so the oil an earlier test left in the job has to be issued again.
func restock() {
	if left := registry.Balance(JobID()); left > 0 {
		testing.IssueCoins(registryAddr, chain.Coins{{registry.Denom, left}})
	}
}

// The whole point of the project in one test: this realm registered a
// callback with another realm at init, and a stranger calling that other
// realm changes this realm's state and is paid for it.
func TestStrangerRotatesTheTap(cur realm, t *testing.T) {
	uassert.Equal(t, "Gnomish Amber", OnTap())
	uassert.Equal(t, int64(0), Rotations())
	uassert.True(t, strings.Contains(Render(""), "The job is out of oil"))

	// A patron funds three rotations.
	oil := chain.Coins{{registry.Denom, 3 * reward}}
	testing.IssueCoins(registryAddr, oil)
	testing.SetRealm(testing.NewUserRealm(patron))
	testing.SetOriginSend(oil)
	registry.Fund(cross(cur), JobID())
	testing.SetOriginSend(nil)
	uassert.True(t, strings.Contains(Render(""), "Next change in 300 seconds"))

	// Too early.
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.False(t, registry.IsDue(JobID()))
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() {
		registry.Exec(cross(cur), JobID())
	})

	// 61 blocks of 5s is 305s, past the 300s rotation.
	testing.SkipHeights(61)
	uassert.True(t, registry.IsDue(JobID()))
	uassert.True(t, strings.Contains(Render(""), "The next change is due now"))

	before := ugnotOf(lighter)
	testing.SetRealm(testing.NewUserRealm(lighter))
	registry.Exec(cross(cur), JobID())

	uassert.Equal(t, "Deep Root Stout", OnTap())
	uassert.Equal(t, int64(1), Rotations())
	uassert.Equal(t, before+reward, ugnotOf(lighter))

	// Same slot again is refused; the next slot works.
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() {
		registry.Exec(cross(cur), JobID())
	})
	testing.SkipHeights(60)
	testing.SetRealm(testing.NewUserRealm(lighter))
	registry.Exec(cross(cur), JobID())
	uassert.Equal(t, "Mushroom Mead", OnTap())
	uassert.Equal(t, int64(2), Rotations())
}

// Nobody but the registry, running the taproom's own job, can reach the callback.
func TestRotateRefusesOtherCallers(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.True(t, rotate(cross(cur), JobID()) != nil, "a user")

	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/impostor"))
	uassert.True(t, rotate(cross(cur), JobID()) != nil, "another realm")
}

func TestRender(t *testing.T) {
	out := Render("")
	uassert.True(t, strings.Contains(out, "# The Taproom"))
	uassert.True(t, strings.Contains(out, "## On tap: "+OnTap()))
	uassert.True(t, strings.Contains(out, "/lamplighter/registry/v2:job/"))
}

// Close ends the job the tests above use.
func TestOnlyTheKeeperCloses(cur realm, t *testing.T) {
	restock()
	keeper = patron // the test runtime's deployer is not an account we can act as

	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.AbortsWithMessage(t, cur, "only the keeper can close the taproom", func() { Close(cross(cur)) })

	left := registry.Balance(JobID())
	uassert.True(t, left > 0)
	before := ugnotOf(patron)

	testing.SetRealm(testing.NewUserRealm(patron))
	Close(cross(cur))
	uassert.Equal(t, before+left, ugnotOf(patron), "the unspent oil comes back")
	uassert.False(t, registry.Exists(JobID()))
	uassert.True(t, strings.Contains(Render(""), "The taproom is closed"))

	uassert.AbortsWithMessage(t, cur, "the taproom is already closed", func() { Close(cross(cur)) })
}

// The registry runs any callback for anyone. Another realm that gets hold of
// this one's callback and posts it as a job of its own, on its own schedule,
// must get nowhere: the job id is not the taproom's.
//
// This test is last because the refused run aborts mid-way. On chain that
// reverts the transaction; the test runtime keeps the registry's lock set.
func TestAnotherRealmCannotScheduleTheTap(cur realm, t *testing.T) {
	restock()
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/attacker"))
	hijack := registry.Register(cross(cur), "hijack", 0, 10, registry.MinReward, rotate)
	uassert.True(t, hijack != JobID())

	testing.IssueCoins(registryAddr, chain.Coins{{registry.Denom, 10 * registry.MinReward}})
	registry.Credit(cross(cur), hijack, 10*registry.MinReward)
	uassert.True(t, registry.IsDue(hijack))

	before := Rotations()
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.AbortsWithMessage(t, cur,
		"job failed: only the taproom's own lamplighter job may change the tap",
		func() { registry.Exec(cross(cur), hijack) })
	uassert.Equal(t, before, Rotations())
}

// Package lastorders auctions the last round of the night: the highest bidder
// buys the round and has a toast written on the tavern wall.
//
// An auction has to end at a set time, and a realm cannot wake itself to end
// it. So every round posts a one-shot Lamplighter job due at its closing
// time: whoever runs that job settles the round, moving the winning bid to the
// seller, and is paid a fee the seller put up when opening the round.
//
// It shows what the taproom example does not: a job per item rather than one
// per realm, a realm funding its own job from coins it was sent
// (registry.Credit), and an owner cleaning up a job that is done.
//
// There is no separate "settle by hand" for a round nobody came for, because
// none is needed: running the job is open to everyone, the seller and the
// winner included.
package lastorders

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

const (
	denom = "ugnot"

	// LampFee is what the seller puts up when opening a round. It pays
	// whoever settles the round on time.
	LampFee int64 = 50000

	// MinBid is the smallest opening bid.
	MinBid int64 = 100000

	// A bid must beat the leading one by at least this many percent.
	raisePercent = 5

	// A round stays open for MinSeconds to MaxSeconds.
	MinSeconds int64 = 60
	MaxSeconds int64 = 7 * 24 * 60 * 60

	maxTitleLen = 60
	maxToastLen = 120
)

// round is one auction.
type round struct {
	id       uint64
	title    string
	seller   address
	closesAt int64
	job      uint64 // the Lamplighter job that settles this round

	leader address
	bid    int64
	toast  string
	bids   int

	settled   bool
	reclaimed bool // the seller has cancelled the finished job
}

var (
	rounds avl.Tree // zero-padded round id -> *round
	byJob  avl.Tree // zero-padded job id -> *round, for the callback
	nextID uint64   = 1
)

// Open starts a round that closes after the given number of seconds. The
// caller is the seller and must send exactly LampFee, which pays whoever
// settles the round on time.
func Open(cur realm, title string, seconds int64) uint64 {
	runtime.AssertOriginCall() // the coins sent are only the caller's on a direct call
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent.AmountOf(denom) != LampFee {
		panic("send exactly " + itoa(LampFee) + " " + denom + ": it pays whoever settles the round on time")
	}
	if !printable(title, maxTitleLen) {
		panic("title must be 1 to " + strconv.Itoa(maxTitleLen) + " bytes of printable text")
	}
	if seconds < MinSeconds || seconds > MaxSeconds {
		panic("a round lasts " + itoa(MinSeconds) + " to " + itoa(MaxSeconds) + " seconds")
	}

	r := &round{
		id:       nextID,
		title:    title,
		seller:   cur.Previous().Address(),
		closesAt: time.Now().Unix() + seconds,
	}
	nextID++

	// Post the job that will settle this round, then fund it: hand the fee
	// to the registry and have it credited to the job, in this same call.
	r.job = registry.Register(cross(cur), "Last Orders: settle round "+utoa(r.id), r.closesAt, 0, LampFee, settleJob)
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), chain.PackageAddress(registry.Path()), chain.Coins{{denom, LampFee}})
	registry.Credit(cross(cur), r.job, LampFee)

	rounds.Set(key(r.id), r)
	byJob.Set(key(r.job), r)

	chain.Emit("RoundOpened", "id", utoa(r.id), "seller", r.seller.String(), "closesAt", itoa(r.closesAt), "job", utoa(r.job))
	return r.id
}

// Bid places a bid of the coins sent with the call, and sets the toast that
// goes on the wall if it wins. The bidder it outbids is refunded at once.
func Bid(cur realm, id uint64, toast string) {
	runtime.AssertOriginCall()
	r := mustRound(id)
	if r.settled || time.Now().Unix() >= r.closesAt {
		panic("the round is closed")
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf(denom)
	if len(sent) != 1 || amount < minNextBid(r) {
		panic("bid at least " + itoa(minNextBid(r)) + " " + denom)
	}
	if !printable(toast, maxToastLen) {
		panic("toast must be 1 to " + strconv.Itoa(maxToastLen) + " bytes of printable text")
	}

	previous, refund := r.leader, r.bid
	r.leader = cur.Previous().Address()
	r.bid = amount
	r.toast = toast
	r.bids++

	// Paying an account runs no code, so this cannot call back in here.
	if refund > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), previous, chain.Coins{{denom, refund}})
	}

	chain.Emit("BidPlaced", "id", utoa(id), "bidder", r.leader.String(), "amount", itoa(amount))
}

// settleJob is the callback the registry holds for every round.
//
// The registry runs any callback for anyone, so "the registry called me" is
// not enough. The job id must be one this realm posted, and it says which
// round to settle.
func settleJob(cur realm, job uint64) error {
	if cur.Previous().PkgPath() != registry.Path() {
		return errors.New("only the lamplighter registry runs this")
	}
	r, ok := byJob.Get(key(job)).(*round)
	if !ok {
		return errors.New("not a job of this realm")
	}
	if r.settled {
		return errors.New("round " + utoa(r.id) + " is already settled")
	}
	if time.Now().Unix() < r.closesAt {
		return errors.New("round " + utoa(r.id) + " is still open")
	}
	settle(cur, r)
	return nil
}

// settle closes a round: the winning bid goes to the seller.
//
// It frees nothing. Whoever sends a transaction that frees state is paid the
// storage deposit that state had locked, so cleaning up here would hand the
// seller's deposit to whoever happened to run the job. Reclaim does it.
func settle(cur realm, r *round) {
	r.settled = true
	if r.bid > 0 {
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), r.seller, chain.Coins{{denom, r.bid}})
	}
	chain.Emit("RoundSettled", "id", utoa(r.id), "winner", r.leader.String(), "amount", itoa(r.bid))
}

// Reclaim cancels the finished job of a settled round. Opening the round
// locked a storage deposit from the seller for that job's state; cancelling
// the job frees the state and the chain releases the deposit to the sender of
// this transaction. Only the seller can call it.
func Reclaim(cur realm, id uint64) {
	r := mustRound(id)
	if cur.Previous().Address() != r.seller {
		panic("only the seller can reclaim the deposit of a round")
	}
	if !r.settled {
		panic("the round is not settled yet")
	}
	if r.reclaimed {
		panic("already reclaimed")
	}
	r.reclaimed = true
	byJob.Remove(key(r.job))
	registry.Cancel(cross(cur), r.job, r.seller)
}

// minNextBid is the smallest bid a round will accept next.
func minNextBid(r *round) int64 {
	if r.bid == 0 {
		return MinBid
	}
	return r.bid + (r.bid*raisePercent+99)/100
}

// Leader returns the leading bidder and bid of a round.
func Leader(id uint64) (address, int64) {
	r := mustRound(id)
	return r.leader, r.bid
}

// Settled reports whether a round has been settled.
func Settled(id uint64) bool { return mustRound(id).settled }

// JobOf returns the Lamplighter job that settles a round.
func JobOf(id uint64) uint64 { return mustRound(id).job }

func mustRound(id uint64) *round {
	r, ok := rounds.Get(key(id)).(*round)
	if !ok {
		panic("unknown round " + utoa(id))
	}
	return r
}

// printable reports whether s is 1 to max bytes of valid, printable text.
func printable(s string, max int) bool {
	if s == "" || len(s) > max || !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	return true
}

func key(id uint64) string {
	s := utoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func utoa(n uint64) string { return strconv.FormatUint(n, 10) }
func itoa(n int64) string  { return strconv.FormatInt(n, 10) }

package lastorders

import (
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

// shown is how many rounds the page lists, newest first.
const shown = 20

func Render(_ string) string {
	now := time.Now().Unix()
	registryURL := strings.TrimPrefix(registry.Path(), "gno.land")

	var b strings.Builder
	b.WriteString("# Last Orders\n\n")
	b.WriteString("The last round of the night goes to the highest bidder, whose toast is written on the wall. ")
	b.WriteString("Each round ends at a set time, and a realm cannot wake itself to end it. ")
	b.WriteString("So every round posts a [Lamplighter](" + registryURL + ") job due at closing time: ")
	b.WriteString("whoever runs it settles the round and is paid " + gnot(LampFee) + " for it.\n\n")

	b.WriteString("[Open a round](" + txlink.NewLink("Open").AddArgs("title", "", "seconds", "600").SetSend(itoa(LampFee)+denom).URL() +
		") (you put up " + gnot(LampFee) + " for the lamplighter)\n\n")

	if rounds.Size() == 0 {
		b.WriteString("No rounds yet.\n")
		return b.String()
	}

	var open, wall strings.Builder
	rounds.ReverseIterateByOffset(0, shown, func(_ string, v any) bool {
		r := v.(*round)
		title := sanitize.TableCell(r.title)
		id := utoa(r.id)
		if !r.settled {
			leading := "no bids"
			if r.bid > 0 {
				leading = gnot(r.bid) + " by " + short(r.leader)
			}
			open.WriteString("| " + id + " | " + title + " | " + leading + " | " + closing(r, now, registryURL) + " | ")
			if now < r.closesAt {
				open.WriteString("[Bid " + gnot(minNextBid(r)) + "](" +
					txlink.NewLink("Bid").AddArgs("id", id, "toast", "").SetSend(itoa(minNextBid(r))+denom).URL() + ")")
			}
			open.WriteString(" |\n")
			return false
		}
		if r.bid == 0 {
			wall.WriteString("| " + id + " | " + title + " | nobody | |\n")
		} else {
			wall.WriteString("| " + id + " | " + title + " | " + short(r.leader) + " for " + gnot(r.bid) +
				" | " + sanitize.TableCell(r.toast) + " |\n")
		}
		return false
	})

	if open.Len() > 0 {
		b.WriteString("## Open rounds\n\n| # | Round | Leading | Closes | |\n|---|---|---|---|---|\n")
		b.WriteString(open.String() + "\n")
	}
	if wall.Len() > 0 {
		b.WriteString("## The wall\n\n| # | Round | Won by | Toast |\n|---|---|---|---|\n")
		b.WriteString(wall.String())
	}
	return b.String()
}

// closing says when a round closes, or what it is waiting for.
func closing(r *round, now int64, registryURL string) string {
	job := "[job " + utoa(r.job) + "](" + registryURL + ":job/" + utoa(r.job) + ")"
	if now < r.closesAt {
		return "in " + itoa(r.closesAt-now) + "s, by " + job
	}
	return "**closed**: run " + job + " to settle it"
}

// short abbreviates an address for a table.
func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// gnot renders an ugnot amount as GNOT with up to six decimals.
func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := itoa(frac)
	for len(f) < 6 {
		f = "0" + f
	}
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

package waveweaver_provenance

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// MinAntiSlopQAPermille enforces WaveWeaver Stage 6 Golden Set QA >= 85.0% (850/1000).
	MinAntiSlopQAPermille = 850
	AnchoredEvent         = "WaveWeaverProvenanceAnchored"
)

// Publication represents an audited, anti-AI-slop calibrated media release anchored on-chain.
type Publication struct {
	Seq              int
	ID               string
	ChannelSlug      string
	Title            string
	Sha256Digest     string
	QAScorePermille  int
	SlopRemovedCount int
	CitationCount    int
	FormatsCSV       string
	SummaryMarkdown  string
	Author           address
}

var (
	pubsByID      avl.Tree // id -> *Publication
	pubsByDigest  avl.Tree // 64-char hex sha256 -> *Publication
	pubsBySeq     avl.Tree // zero-padded seq -> *Publication
	channelCounts avl.Tree // channelSlug -> int
	nextSeq       int
)

func normalizeSha256(raw string) string {
	s := strings.ToLower(strings.TrimSpace(raw))
	if strings.HasPrefix(s, "0x") {
		s = s[2:]
	}
	if len(s) != 64 {
		panic("waveweaver: sha256 digest must be 64 hex characters")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			panic("waveweaver: sha256 digest contains non-hex character")
		}
	}
	return s
}

func cleanSlug(raw string) string {
	s := strings.TrimSpace(raw)
	if s == "" || len(s) > 64 {
		panic("waveweaver: invalid identifier or channel slug")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			panic("waveweaver: slug may only contain [a-zA-Z0-9_-]")
		}
	}
	return s
}

func padSeq(n int) string {
	s := strconv.Itoa(n)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

func formatPermille(p int) string {
	whole := p / 10
	frac := p % 10
	return ufmt.Sprintf("%d.%d", whole, frac)
}

func jsonEscape(s string) string {
	out := strings.ReplaceAll(s, "\\", "\\\\")
	out = strings.ReplaceAll(out, "\"", "\\\"")
	out = strings.ReplaceAll(out, "\n", " ")
	out = strings.ReplaceAll(out, "\r", " ")
	return out
}

// AnchorPublication enforces deterministic Anti-AI-Slop & citation invariants before committing on-chain provenance.
func AnchorPublication(
	cur realm,
	id string,
	channelSlug string,
	title string,
	sha256Digest string,
	qaScorePermille int,
	slopRemovedCount int,
	citationCount int,
	formatsCSV string,
	summaryMarkdown string,
) string {
	cleanID := cleanSlug(id)
	cleanCh := cleanSlug(channelSlug)
	cleanTitle := strings.TrimSpace(title)
	if cleanTitle == "" || len(cleanTitle) > 200 {
		panic("waveweaver: title must be 1..200 chars")
	}
	normHash := normalizeSha256(sha256Digest)

	if qaScorePermille < MinAntiSlopQAPermille || qaScorePermille > 1000 {
		panic("waveweaver: Stage 6 Anti-AI-Slop QA score below 850 permille (85.0%) minimum gate")
	}
	if slopRemovedCount < 0 {
		panic("waveweaver: slopRemovedCount must be non-negative")
	}
	if citationCount < 1 {
		panic("waveweaver: at least 1 verified primary-source citation is required")
	}
	if pubsByID.Has(cleanID) {
		panic("waveweaver: duplicate publication ID")
	}
	if pubsByDigest.Has(normHash) {
		panic("waveweaver: duplicate sha256 content digest already anchored")
	}

	cleanFormats := strings.TrimSpace(formatsCSV)
	if cleanFormats == "" {
		cleanFormats = "9:16_AVATAR_VIDEO,VISUAL_CAROUSEL,LONG_ARTICLE,PODCAST_AUDIO,MICRO_THREAD"
	}
	cleanSummary := strings.TrimSpace(summaryMarkdown)
	if len(cleanSummary) > 1200 {
		cleanSummary = cleanSummary[:1200]
	}

	caller := cur.Previous().Address()
	nextSeq++
	pub := &Publication{
		Seq:              nextSeq,
		ID:               cleanID,
		ChannelSlug:      cleanCh,
		Title:            cleanTitle,
		Sha256Digest:     normHash,
		QAScorePermille:  qaScorePermille,
		SlopRemovedCount: slopRemovedCount,
		CitationCount:    citationCount,
		FormatsCSV:       cleanFormats,
		SummaryMarkdown:  cleanSummary,
		Author:           caller,
	}

	pubsByID.Set(cleanID, pub)
	pubsByDigest.Set(normHash, pub)
	pubsBySeq.Set(padSeq(nextSeq), pub)

	prevCount := 0
	if v := channelCounts.Get(cleanCh); v != nil {
		prevCount = v.(int)
	}
	channelCounts.Set(cleanCh, prevCount+1)

	chain.Emit(
		AnchoredEvent,
		"id", cleanID,
		"channel", cleanCh,
		"sha256", normHash,
		"qa_permille", strconv.Itoa(qaScorePermille),
		"author", caller.String(),
	)

	return ufmt.Sprintf("ANCHORED:%s:0x%s:QA=%s", cleanID, normHash, formatPermille(qaScorePermille))
}

// VerifyDigest allows AI agents (via gnomcp) and readers to verify a SHA-256 content digest without gas.
func VerifyDigest(sha256Digest string) string {
	s := strings.ToLower(strings.TrimSpace(sha256Digest))
	if strings.HasPrefix(s, "0x") {
		s = s[2:]
	}
	if len(s) != 64 {
		return `{"verified":false,"error":"invalid_sha256_length"}`
	}
	raw := pubsByDigest.Get(s)
	if raw == nil {
		return ufmt.Sprintf(`{"verified":false,"sha256":"0x%s"}`, s)
	}
	pub := raw.(*Publication)
	return ufmt.Sprintf(
		`{"verified":true,"seq":%d,"id":"%s","channel":"%s","title":"%s","sha256":"0x%s","qa_score":"%s","citations":%d,"slop_removed":%d,"author":"%s"}`,
		pub.Seq,
		jsonEscape(pub.ID),
		jsonEscape(pub.ChannelSlug),
		jsonEscape(pub.Title),
		pub.Sha256Digest,
		formatPermille(pub.QAScorePermille),
		pub.CitationCount,
		pub.SlopRemovedCount,
		pub.Author.String(),
	)
}

// TotalPublications returns the total count of verified publications anchored in this realm.
func TotalPublications() int {
	return pubsByID.Size()
}

// ChannelCount returns the number of isolated WaveWeaver content channels with anchored records.
func ChannelCount() int {
	return channelCounts.Size()
}

// Render serves native gnoweb Markdown views:
//   - ""                  -> Registry dashboard, channel isolation summary & verified publications
//   - "channel/<slug>"    -> Channel-scoped publications
//   - "pub/<id>"          -> Full provenance certificate for a single publication
//   - "verify/<sha256>"   -> Direct SHA-256 digest lookup
func Render(path string) string {
	cleanPath := strings.Trim(path, "/")
	if strings.HasPrefix(cleanPath, "pub/") {
		return renderPublicationDetail(strings.TrimPrefix(cleanPath, "pub/"))
	}
	if strings.HasPrefix(cleanPath, "channel/") {
		return renderDashboard(strings.TrimPrefix(cleanPath, "channel/"))
	}
	if strings.HasPrefix(cleanPath, "verify/") {
		return renderVerify(strings.TrimPrefix(cleanPath, "verify/"))
	}
	return renderDashboard("")
}

func renderDashboard(filterChannel string) string {
	var b strings.Builder
	b.WriteString("# WaveWeaver — On-Chain Anti-AI-Slop Content Provenance Registry\n\n")
	b.WriteString("> **8-Stage Human-in-the-Loop AI Media OS**: Stage 5 Anti-AI-Slop Calibration + Stage 6 Golden Set QA Gate (`>= 85.0`) + Stage 8 `SHA-256` Provenance Realm.\n\n")
	b.WriteString(ufmt.Sprintf(
		"- **Verified Publications Anchored**: `%d`  \n- **Isolated Content Channels**: `%d`  \n- **Deterministic On-Chain Gate**: `QAScore >= 85.0` & `Primary Citations >= 1`\n\n",
		pubsByID.Size(),
		channelCounts.Size(),
	))

	if channelCounts.Size() > 0 {
		b.WriteString("## Isolated Multi-Tenant Channels (`Org -> Workspace -> ContentChannel`)\n\n")
		channelCounts.Iterate("", "", func(chKey string, val any) bool {
			cnt := val.(int)
			b.WriteString(ufmt.Sprintf("- **`%s`** (`%d` verified releases) — [Filter Channel](?:/channel/%s)\n", chKey, cnt, chKey))
			return false
		})
		if filterChannel != "" {
			b.WriteString(ufmt.Sprintf("\n*Showing channel filter: `%s` — [Back to All Channels](?:)*\n", filterChannel))
		}
		b.WriteString("\n")
	}

	b.WriteString("## Anchored Content Provenance Ledger\n\n")
	if pubsBySeq.Size() == 0 {
		b.WriteString("*No publications anchored yet.*\n")
		return b.String()
	}

	b.WriteString("| # | Publication ID | Channel | Title | Anti-Slop QA | Citations | SHA-256 Digest |\n")
	b.WriteString("| :--- | :--- | :--- | :--- | :--- | :--- | :--- |\n")

	pubsBySeq.ReverseIterate("", "", func(_ string, val any) bool {
		pub := val.(*Publication)
		if filterChannel != "" && pub.ChannelSlug != filterChannel {
			return false
		}
		shortHash := pub.Sha256Digest[:10] + "..." + pub.Sha256Digest[56:]
		b.WriteString(ufmt.Sprintf(
			"| %d | [`%s`](?:/pub/%s) | `%s` | %s | **%s / 100** (`-%d` slop) | `%d` | `0x%s` |\n",
			pub.Seq,
			pub.ID,
			pub.ID,
			pub.ChannelSlug,
			pub.Title,
			formatPermille(pub.QAScorePermille),
			pub.SlopRemovedCount,
			pub.CitationCount,
			shortHash,
		))
		return false
	})

	return b.String()
}

func renderPublicationDetail(id string) string {
	raw := pubsByID.Get(strings.TrimSpace(id))
	if raw == nil {
		return ufmt.Sprintf("# Publication Not Found\n\nNo anchored publication matches ID `%s`.\n", id)
	}
	pub := raw.(*Publication)
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Provenance Certificate · `%s`\n\n", pub.ID))
	b.WriteString(ufmt.Sprintf("- **Title**: %s\n", pub.Title))
	b.WriteString(ufmt.Sprintf("- **Isolated Channel**: `%s`\n", pub.ChannelSlug))
	b.WriteString(ufmt.Sprintf("- **Canonical SHA-256 Digest**: `0x%s`\n", pub.Sha256Digest))
	b.WriteString(ufmt.Sprintf("- **Stage 6 Golden Set QA Score**: **`%s / 100.0`** (`%d` LLM slop clichés stripped)\n", formatPermille(pub.QAScorePermille), pub.SlopRemovedCount))
	b.WriteString(ufmt.Sprintf("- **Verified Primary Citations**: `%d`\n", pub.CitationCount))
	b.WriteString(ufmt.Sprintf("- **5 Synchronized Media Formats**: `%s`\n", pub.FormatsCSV))
	b.WriteString(ufmt.Sprintf("- **Anchored By**: `%s`\n\n", pub.Author.String()))
	if pub.SummaryMarkdown != "" {
		b.WriteString("## Calibrated Executive Summary\n\n")
		b.WriteString(pub.SummaryMarkdown + "\n\n")
	}
	b.WriteString("[<- Back to Provenance Registry](?:)\n")
	return b.String()
}

func renderVerify(digest string) string {
	return "# SHA-256 Digest Verification\n\n```json\n" + VerifyDigest(digest) + "\n```\n\n[<- Back to Provenance Registry](?:)\n"
}

