package mandate

import (
	"strconv"
	"strings"
	"time"
)

// Free reads. Each returns plain values (copies), never pointers into the
// realm's state, so callers and vm/qeval cannot change anything.

// PlanInfo is a copy of a plan.
type PlanInfo struct {
	ID        uint64
	Payee     address
	Title     string
	Amount    int64
	Period    int64
	CreatedAt int64
	Mandates  int // mandates ever created for this plan
	Cancelled int // how many of them were cancelled
	// PaidThisPeriod and PaidLastPeriod count the payments in the plan's
	// current period window, which started at PeriodStart, and in the window
	// before it. Windows are [k*Period, (k+1)*Period) in unix time. They count
	// payments, not distinct people (a creator can pay its own plan from a
	// second wallet). Historical facts, true at any time, whatever has
	// expired or been cancelled since.
	PaidThisPeriod int
	PaidLastPeriod int
	PeriodStart    int64
	Pulls          int64
	Paid           int64
	LastPullAt     int64
}

// MandateInfo is a copy of a mandate with the realm's view of it.
type MandateInfo struct {
	ID            uint64
	PlanID        uint64
	Payer         address
	Payee         address
	Session       address
	SessionPubKey string
	Amount        int64
	Period        int64
	CreatedAt     int64
	ExpiresAt     int64
	NextPullAt    int64
	LastPullAt    int64
	// PaidThrough is until when this mandate's payments, or paid time
	// carried over from the payer's earlier mandate for the plan, cover the
	// payer (0 if neither). A mandate that starts with carried time has its
	// first pull at that time.
	PaidThrough int64
	Pulls       int64
	Paid        int64
	CancelledAt int64
	CancelledBy address
	// Status is "active", "expired" or "cancelled": the realm's view only.
	Status string
	// Due is true when the mandate is active and a pull is allowed now.
	Due bool
	// SessionPubKey is the session key's public key when it is the payee's
	// current collector key, "" otherwise.
	//
	// SessionQuery is the free query an off-chain checker must also run:
	// the realm cannot see a session revoked or expired on chain.
	SessionQuery string
}

// PayeeInfo is a copy of a payee's totals and collector key.
type PayeeInfo struct {
	Addr          address
	Plans         int
	Pulls         int64
	Paid          int64
	LastPullAt    int64
	CollectorKey  string
	CollectorAddr address
	// CollectorFunded is true when the collector key's address holds coins:
	// the chain then refuses every new session for that key, so nobody can
	// subscribe until the creator publishes a new key. (An address that
	// received coins and was emptied is also refused by the chain; only the
	// free query auth/accounts/<CollectorAddr> shows that.)
	CollectorFunded bool
}

// GetPlan returns the plan with this id.
func GetPlan(id uint64) (PlanInfo, bool) {
	p := planOf(id)
	if p == nil {
		return PlanInfo{}, false
	}
	return p.info(), true
}

// MandateOf returns the latest mandate of payer for this session address.
func MandateOf(payer, sessionAddr address) (MandateInfo, bool) {
	m := latestBySession(payer, sessionAddr)
	if m == nil {
		return MandateInfo{}, false
	}
	return m.info(time.Now().Unix()), true
}

// PaidThrough is the read for services that deliver something to paying
// supporters. It returns the unix time until which the payer's payments for
// the plan cover them: the latest payment's time plus one period. Paid time
// stays the payer's when a mandate is cancelled (by either side) or
// expires, and a new mandate for the same plan starts when it ends, so it
// is not charged twice. The one exception: a payer who already holds 16
// kept periods (MaxCreditsPerPayer). 0 when they never paid for the plan.
// Deliver while now < PaidThrough.
//
// It turns false at the due time and moves on only when the payee's
// collector pulls the next payment: allow a grace equal to how often the
// collector runs (an hour, say) before treating a supporter as lapsed.
//
// A payment is proof; a mandate is not: anyone can record a mandate
// without creating a session and without paying. A realm also cannot see a
// session revoked on chain: a revoked supporter simply stops paying, so
// PaidThrough stops moving and runs out within one period.
func PaidThrough(payer address, planID uint64) int64 {
	pr := payerOf(payer)
	if pr == nil {
		return 0
	}
	now := time.Now().Unix()
	until := pr.creditFor(planID, now)
	for _, r := range pr.Active {
		if r.PlanID == planID {
			if t := r.M.paidThrough(); t > until {
				until = t
			}
		}
	}
	return until
}

// IsPaidUp reports whether payer's latest payment for the plan still covers
// now (now < PaidThrough). See PaidThrough.
func IsPaidUp(payer address, planID uint64) bool {
	return time.Now().Unix() < PaidThrough(payer, planID)
}

// HasMandate reports whether payer has a mandate for the plan that is
// neither cancelled nor expired in the realm. It says nothing about payment
// (a mandate costs only a storage deposit to record) and cannot see a
// session revoked on chain: do not grant anything on it; use PaidThrough.
func HasMandate(payer address, planID uint64) bool {
	m := activeByPlan(payer, planID)
	return m != nil && m.isActive(time.Now().Unix())
}

// NextPullAt returns when the next pull of payer's active mandate for the
// plan is allowed (unix seconds), or 0 if there is no active mandate.
func NextPullAt(payer address, planID uint64) int64 {
	m := activeByPlan(payer, planID)
	if m == nil || !m.isActive(time.Now().Unix()) {
		return 0
	}
	return m.NextPullAt
}

// GetPayee returns a payee's totals and collector key.
func GetPayee(payee address) (PayeeInfo, bool) {
	pe := payeeOf(payee)
	if pe == nil {
		return PayeeInfo{}, false
	}
	return PayeeInfo{
		Addr:            pe.Addr,
		Plans:           pe.Plans,
		Pulls:           pe.Pulls,
		Paid:            pe.Paid,
		LastPullAt:      pe.LastPullAt,
		CollectorKey:    pe.CollectorKey,
		CollectorAddr:   pe.CollectorAddr,
		CollectorFunded: pe.CollectorKey != "" && collectorFunded(pe.CollectorAddr),
	}, true
}

// Totals returns the number of plans and mandates, and all pulls so far.
func Totals() (plansCount, mandatesCount int, pulls, paid int64) {
	return plans.Size(), int(nextMandateID), totalPulls, totalPaid
}

// Plans lists all plans, newest first, PageSize per page (page 1 first).
func Plans(page int) []PlanInfo {
	out := []PlanInfo{}
	plans.ReverseIterateByOffset(offset(page), PageSize, func(_ string, v any) bool {
		out = append(out, v.(*Plan).info())
		return false
	})
	return out
}

// PlansOf lists a payee's plans, oldest first.
func PlansOf(payee address, page int) []PlanInfo {
	out := []PlanInfo{}
	plans, _ := payeePlans(payee, page)
	for _, p := range plans {
		out = append(out, p.info())
	}
	return out
}

// payeePlans returns page `page` of a payee's plans and whether more follow.
func payeePlans(payee address, page int) ([]*Plan, bool) {
	pe := payeeOf(payee)
	if pe == nil {
		return nil, false
	}
	lo, hi, more := pageBounds(pe.planIDs.N, page)
	out := make([]*Plan, 0, hi-lo)
	for i := lo; i < hi; i++ {
		id, _ := strconv.ParseUint(pe.planIDs.at(i), 10, 64)
		out = append(out, planOf(id))
	}
	return out, more
}

// MandatesOf lists a payer's mandates (all states), newest first.
func MandatesOf(payer address, page int) []MandateInfo {
	list, _ := payerPage(payer, page)
	return infos(list)
}

// payerPage returns page `page` of the payer's mandates, newest first, and
// whether another page follows. It walks the payer's history, which only
// free reads do.
func payerPage(payer address, page int) ([]*Mandate, bool) {
	skip := offset(page)
	out := []*Mandate{}
	for m := payerHead(payer); m != nil; m = m.prevOfPayer {
		if skip > 0 {
			skip--
			continue
		}
		if len(out) == PageSize {
			return out, true
		}
		out = append(out, m)
	}
	return out, false
}

// SupportersOf lists a plan's active mandates (not cancelled, replaced or
// expired), oldest first. Page n covers entries (n-1)*PageSize to
// n*PageSize-1 of the plan's list, so a page may hold fewer rows than
// PageSize; inactive ones are on the payers' own pages.
func SupportersOf(planID uint64, page int) []MandateInfo {
	p := planOf(planID)
	if p == nil {
		return []MandateInfo{}
	}
	now := time.Now().Unix()
	out := []MandateInfo{}
	lo, hi, _ := pageBounds(p.Supporters.N, page)
	for i := lo; i < hi; i++ {
		e := decodeEntry(p.Supporters.at(i))
		if e.Status == statusCancelled {
			continue
		}
		if m := activeMandate(e); m != nil && m.isActive(now) {
			out = append(out, m.info(now))
		}
	}
	return out
}

// ScanLimit is the most supporter-list entries one free read resolves
// (looks up in its payer's record); WalkLimit is the most it reads at all.
// Entries carry their status, so cancelled ones, and for some reads unpaid
// ones, are skipped without a lookup. Reads that filter return a cursor to
// continue from, so junk can delay but never hide a real entry.
const (
	ScanLimit = 200
	WalkLimit = 1000
)

// CollectorPlans lists a payee's plans for a collector script, one per line:
//
//	<plan id> <amount ugnot> <period seconds> <mandates>
//
// PageSize per page; the last line is "more" or "end".
func CollectorPlans(payee address, page int) string {
	var b strings.Builder
	more := false
	if list, m := payeePlans(payee, page); list != nil {
		more = m
		for _, p := range list {
			b.WriteString(utoa(p.ID) + " " + itoa(p.Amount) + " " + itoa(p.Period) + " " + strconv.Itoa(p.Supporters.N) + "\n")
		}
	}
	if more {
		b.WriteString("more\n")
	} else {
		b.WriteString("end\n")
	}
	return b.String()
}

// CollectorScan walks at most ScanLimit entries of a plan's supporter list,
// from index `from` (0 = oldest), and returns the active mandates whose
// session key is sessionAddr, one per line:
//
//	<index> <mandate id> <payer> <amount ugnot> <next pull unix> <due|wait> <pulls> <paid>
//
// <paid> is 1 when the payer has paid for this plan (this mandate pulled, or
// it started with paid time carried over from an earlier one), 0 when it
// never has. The last line is "next <index>" when more entries follow,
// "end" otherwise. Cancelled and expired mandates, and mandates for other
// keys, are skipped here, so a collector never needs to read them. Anyone
// can record a mandate without a session, so a collector should check on
// chain that the session exists, at least before the first pull of a
// mandate whose payer never paid.
func CollectorScan(planID uint64, sessionAddr address, from int) string {
	p := planOf(planID)
	if p == nil {
		return "end\n"
	}
	if from < 0 {
		from = 0
	}
	if from > p.Supporters.N {
		from = p.Supporters.N // also keeps from+ScanLimit from overflowing
	}
	now := time.Now().Unix()
	var b strings.Builder
	end := from + ScanLimit
	if end > p.Supporters.N {
		end = p.Supporters.N
	}
	for i := from; i < end; i++ {
		e := decodeEntry(p.Supporters.at(i))
		if e.Status == statusCancelled {
			continue
		}
		pr := payerOf(e.Payer)
		if pr == nil {
			continue
		}
		var m *Mandate
		for _, r := range pr.Active {
			if r.ID == e.ID && r.Session == sessionAddr {
				m = r.M
			}
		}
		if m == nil || !m.isActive(now) {
			continue
		}
		due := "wait"
		if now >= m.NextPullAt {
			due = "due"
		}
		b.WriteString(strconv.Itoa(i) + " " + utoa(m.ID) + " " + m.Payer.String() + " " + itoa(p.Amount) + " " +
			itoa(m.NextPullAt) + " " + due + " " + itoa(m.Pulls) + " " + paidFlag(m) + "\n")
	}
	if end < p.Supporters.N {
		b.WriteString("next " + strconv.Itoa(end) + "\n")
	} else {
		b.WriteString("end\n")
	}
	return b.String()
}

// payingFrom lists a plan's supporters: mandates that have paid at least
// once and are active now, newest first, up to PageSize, starting at list
// index `from` (or the newest when from < 0). It reads at most WalkLimit
// entries and resolves at most ScanLimit of them (only entries marked paid
// are resolved), and returns the index to continue from (-1 when the list is
// exhausted).
func payingFrom(p *Plan, from int, now int64) ([]*Mandate, int) {
	if from < 0 || from >= p.Supporters.N {
		from = p.Supporters.N - 1
	}
	out := []*Mandate{}
	i, walked, resolved := from, 0, 0
	for ; i >= 0 && walked < WalkLimit && resolved < ScanLimit && len(out) < PageSize; i, walked = i-1, walked+1 {
		e := decodeEntry(p.Supporters.at(i))
		if e.Status != statusPaid {
			continue
		}
		resolved++
		if m := activeMandate(e); m != nil && m.isActive(now) {
			out = append(out, m)
		}
	}
	return out, i
}

// PayingSupporters lists a plan's supporters the way its gnoweb page does:
// mandates that have paid at least once and are active now, newest first,
// at most PageSize per call. Pass from = -1 for the newest; the second
// result is where to continue. A client must stop when it is -1 (the list
// is exhausted): -1 passed back in starts again from the newest, so a
// client that feeds the cursor back unchecked loops for ever. Each call
// walks at most WalkLimit entries and looks up at most ScanLimit of them,
// so a call may return fewer than PageSize (even none) and still a cursor.
func PayingSupporters(planID uint64, from int) ([]MandateInfo, int) {
	p := planOf(planID)
	if p == nil {
		return []MandateInfo{}, -1
	}
	now := time.Now().Unix()
	list, next := payingFrom(p, from, now)
	out := make([]MandateInfo, 0, len(list))
	for _, m := range list {
		out = append(out, m.info(now))
	}
	return out, next
}

// PlanCounts returns the numbers the gnoweb plan page shows: how many
// supporters paid in the plan's current period window and in the one
// before (as in GetPlan), and how many active mandates have never paid,
// among the latest ScanLimit entries (unpaidExact is false when there were
// more entries than that).
func PlanCounts(planID uint64) (paidThisPeriod, paidLastPeriod, unpaid int, unpaidExact bool) {
	p := planOf(planID)
	if p == nil {
		return 0, 0, 0, true
	}
	now := time.Now().Unix()
	paidThisPeriod, paidLastPeriod = p.paidWindows(now)
	unpaid, unpaidExact = countUnpaid(p, now)
	return
}

// countUnpaid counts active mandates that have never paid, among the
// plan's latest ScanLimit mandates, and says whether that covered them all.
func countUnpaid(p *Plan, now int64) (int, bool) {
	n := 0
	lo := p.Supporters.N - ScanLimit
	if lo < 0 {
		lo = 0
	}
	for i := p.Supporters.N - 1; i >= lo; i-- {
		e := decodeEntry(p.Supporters.at(i))
		if e.Status != statusUnpaid {
			continue
		}
		if m := activeMandate(e); m != nil && m.isActive(now) {
			n++
		}
	}
	return n, lo == 0
}

func infos(list []*Mandate) []MandateInfo {
	now := time.Now().Unix()
	out := []MandateInfo{}
	for _, m := range list {
		out = append(out, m.info(now))
	}
	return out
}

func (p *Plan) info() PlanInfo {
	now := time.Now().Unix()
	current, previous := p.paidWindows(now)
	return PlanInfo{
		ID:             p.ID,
		Payee:          p.Payee,
		Title:          p.Title,
		Amount:         p.Amount,
		Period:         p.Period,
		CreatedAt:      p.CreatedAt,
		Mandates:       p.Supporters.N,
		Cancelled:      p.Cancelled,
		PaidThisPeriod: current,
		PaidLastPeriod: previous,
		PeriodStart:    now / p.Period * p.Period,
		Pulls:          p.Pulls,
		Paid:           p.Pulls * p.Amount,
		LastPullAt:     p.LastPullAt,
	}
}

func (m *Mandate) info(now int64) MandateInfo {
	p := m.plan
	st := m.status(now)
	return MandateInfo{
		ID:            m.ID,
		PlanID:        p.ID,
		Payer:         m.Payer,
		Payee:         p.Payee,
		Session:       m.Session,
		SessionPubKey: m.sessionPubKey(),
		Amount:        p.Amount,
		Period:        p.Period,
		CreatedAt:     m.CreatedAt,
		ExpiresAt:     m.ExpiresAt,
		NextPullAt:    m.NextPullAt,
		LastPullAt:    m.lastPullAt(),
		PaidThrough:   m.paidThrough(),
		Pulls:         m.Pulls,
		Paid:          m.Pulls * p.Amount,
		CancelledAt:   m.CancelledAt,
		CancelledBy:   m.CancelledBy,
		Status:        st,
		Due:           st == "active" && now >= m.NextPullAt,
		SessionQuery:  "auth/accounts/" + m.Payer.String() + "/session/" + m.Session.String(),
	}
}

// lastPullAt is when the last pull happened (0 = never): each pull sets
// NextPullAt to its own time plus one period.
func (m *Mandate) lastPullAt() int64 {
	if m.Pulls == 0 {
		return 0
	}
	return m.NextPullAt - m.plan.Period
}

// sessionPubKey returns the session key's public key when it is the payee's
// current collector key, "" otherwise (the realm then does not know it).
func (m *Mandate) sessionPubKey() string {
	if pe := m.plan.payee; pe.CollectorAddr == m.Session {
		return pe.CollectorKey
	}
	return ""
}

// offset turns a 1-based page number into a row offset; pages below 1 and
// absurdly large pages are clamped.
func offset(page int) int {
	if page < 1 {
		page = 1
	}
	if page > 1_000_000 {
		page = 1_000_000
	}
	return (page - 1) * PageSize
}

// pageBounds returns the slice bounds of page `page` (1-based, PageSize
// rows) in a list of n rows, and whether another page follows.
func pageBounds(n, page int) (lo, hi int, more bool) {
	lo = offset(page)
	if lo > n {
		lo = n
	}
	hi = lo + PageSize
	if hi > n {
		hi = n
	}
	return lo, hi, hi < n
}

// paidFlag is CollectorScan's last column: "1" once the payer has paid for
// the plan through this mandate or carried paid time into it, else "0".
func paidFlag(m *Mandate) string {
	if m.paidThrough() > 0 {
		return "1"
	}
	return "0"
}

package mandate

import (
	"strconv"
	"strings"
	"time"
)

// SourceRepo is where the source code is published, shown in the footer of
// every page.
const SourceRepo = "https://github.com/elangrr/mandate"

// Network the copy-ready commands are pinned to.
const (
	ChainID = "onyx-1"
	Remote  = "https://rpc.onyx.testnets.gno.land:443"
)

// Gas settings used in the commands. The chain charges the whole fee set,
// whatever gas is used, and accepts it when fee / gas wanted is at least
// the current gas price (1 ugnot per 1,000 gas on Onyx). Measured on a local
// chain: Offer and Subscribe use 7M to 10M gas, Pull 8M to 9M. Reads on
// Onyx cost more per object (the chain prices a read by its store's depth,
// and Onyx's store is far larger), so gas wanted keeps about 2x headroom.
// The Pull fee counts against the session's spend limit (see FeeAllowance).
const (
	callGas = "-gas-fee 100000ugnot -gas-wanted 60000000"
	pullGas = "-gas-fee 20000ugnot -gas-wanted 20000000"
)

// Render returns the gnoweb page for path, with the footer.
func Render(path string) string {
	return renderPage(path) + footer()
}

func footer() string {
	return "\n---\n\nBuilt on [gno.land](https://gno.land) · source code: [" + strings.TrimPrefix(SourceRepo, "https://") + "](" + SourceRepo + ")\n"
}

func renderPage(raw string) string {
	path, query := raw, ""
	if i := strings.Index(raw, "?"); i >= 0 {
		path, query = raw[:i], raw[i+1:]
	}
	page := pageParam(query)
	from := intParam(query, "from", -1)
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome(from)
	case path == "plans":
		return renderAllPlans(page)
	case path == "help":
		return renderHelp()
	case len(parts) == 2 && parts[0] == "plan":
		id, err := strconv.ParseUint(parts[1], 10, 64)
		if err != nil {
			return renderNotFound()
		}
		return renderPlan(id, from)
	case len(parts) == 2 && parts[0] == "payer":
		a := address(parts[1])
		if !a.IsValid() {
			return renderNotFound()
		}
		return renderPayer(a, page)
	case len(parts) == 2 && parts[0] == "payee":
		a := address(parts[1])
		if !a.IsValid() {
			return renderNotFound()
		}
		return renderPayee(a, page)
	}
	return renderNotFound()
}

func renderHome(from int) string {
	nPlans, nMandates, pulls, paid := Totals()
	var b strings.Builder
	b.WriteString("# Mandate\n\n")
	b.WriteString("**Subscriptions and direct debit on native GNOT.** A creator publishes a plan, such as 1 GNOT every week. ")
	b.WriteString("A supporter signs one permission from their own wallet: *at most this much, every period, through this realm only, until I cancel or it expires*. ")
	b.WriteString("The creator's collector then pulls each payment at the start of the period, and this realm checks who, how much and when before it forwards the coins.\n\n")
	b.WriteString("## The honest limits\n\n")
	b.WriteString("- **It is direct debit, not escrow.** Nothing is locked up front. A supporter can stop at any time, and a creator is only paid when a pull succeeds.\n")
	b.WriteString("- **A hard cap the supporter sets.** The chain never lets a pull take more than the session's spend limit per period: the plan's amount plus a fee allowance of " + formatUgnot(FeeAllowance) + ". ")
	b.WriteString("A dishonest creator could at worst burn that allowance as network fees; they can never take more, or pull more often.\n")
	b.WriteString("- **At most " + strconv.Itoa(MaxSessionsPerWallet) + " mandates per wallet**, because the chain allows " + strconv.Itoa(MaxSessionsPerWallet) + " session keys per account.\n")
	b.WriteString("- **Revoke any time.** Revoking the session on chain stops every pull at once. The realm cannot see a revoke, so a mandate still shows here as active until it is cancelled or expires: [how to stop a mandate](" + link("help") + ").\n")
	b.WriteString("- **One realm, nothing under it.** A session for this realm also covers any realm deployed under its path, so nothing will ever be deployed there.\n")
	b.WriteString("- No admin, no pause, no upgrade. The realm never holds funds: each payment goes straight to the creator in the same transaction.\n\n")
	b.WriteString("[How to use it, with every command](" + link("help") + ")\n\n")
	b.WriteString("## Numbers\n\n")
	b.WriteString("| Plans | Mandates ever recorded | Payments | Paid out |\n|---|---|---|---|\n")
	b.WriteString("| " + strconv.Itoa(nPlans) + " | " + strconv.Itoa(nMandates) + " | " + itoa(pulls) + " | " + formatUgnot(paid) + " |\n\n")
	b.WriteString("## Supporter pages\n\n")
	b.WriteString(plansWithSupporters(from))
	return b.String()
}

// homeScanPlans is how many plans one home page walks. Each check reads only
// the plan itself (its payment counters), never its supporters.
const homeScanPlans = ScanLimit

// plansWithSupporters lists, newest first, the plans that someone paid in
// the current or the previous period, walking at most homeScanPlans plans
// per page: plans nobody pays for (spam included) never fill this list, and
// a "more" link continues the walk. A plan someone keeps paying for stays,
// whatever the churn of its supporter list.
func plansWithSupporters(from int) string {
	var b strings.Builder
	n := plans.Size()
	if from < 0 || from >= n {
		from = n - 1
	}
	rows := 0
	i := from
	now := time.Now().Unix()
	var t strings.Builder
	for walked := 0; i >= 0 && walked < homeScanPlans && rows < PageSize; i, walked = i-1, walked+1 {
		_, v := plans.GetByIndex(i)
		p := v.(*Plan)
		if current, previous := p.paidWindows(now); current+previous == 0 {
			continue
		}
		t.WriteString("| [#" + utoa(p.ID) + " " + escCell(p.Title) + "](" + link("plan/"+utoa(p.ID)) + ") | " + price(p.Amount, p.Period) +
			" | [" + short(p.Payee) + "](" + link("payee/"+p.Payee.String()) + ") | " + payingCell(p, now) +
			" | " + itoa(p.Pulls) + " |\n")
		rows++
	}
	if rows == 0 {
		b.WriteString("No plan has been paid for in its current or last period")
		if i >= 0 {
			b.WriteString(" among those looked at")
		}
		b.WriteString(".\n\n")
	} else {
		b.WriteString("| Plan | Price | Creator | Payments this / last period | All payments |\n|---|---|---|---|---|\n")
		b.WriteString(t.String() + "\n")
	}
	if i >= 0 {
		b.WriteString("[More plans with supporters](" + link("") + "?from=" + strconv.Itoa(i) + ")\n\n")
	}
	b.WriteString("Only plans that someone has paid for are listed here. [All plans, newest first](" + link("plans") + ")\n")
	return b.String()
}

func renderAllPlans(page int) string {
	var b strings.Builder
	b.WriteString("# All plans\n\nNewest first, including plans nobody has paid for yet. [Back to Mandate](" + link("") + ")\n\n")
	list := Plans(page)
	if len(list) == 0 {
		b.WriteString("No plans on this page.\n")
		return b.String()
	}
	b.WriteString("| Plan | Price | Creator | Payments this / last period | All payments |\n|---|---|---|---|---|\n")
	for _, p := range list {
		b.WriteString("| [#" + utoa(p.ID) + " " + escCell(p.Title) + "](" + link("plan/"+utoa(p.ID)) + ") | " + price(p.Amount, p.Period) +
			" | [" + short(p.Payee) + "](" + link("payee/"+p.Payee.String()) + ") | " + infoPayingCell(p) +
			" | " + itoa(p.Pulls) + " |\n")
	}
	b.WriteString(pager("plans", page, len(list) == PageSize))
	return b.String()
}

func renderPlan(id uint64, from int) string {
	p := planOf(id)
	if p == nil {
		return renderNotFound()
	}
	now := time.Now().Unix()
	pe := payeeOf(p.Payee)
	var b strings.Builder
	b.WriteString("# Plan #" + utoa(p.ID) + ": " + esc(p.Title) + "\n\n")
	b.WriteString("**" + price(p.Amount, p.Period) + "** to [" + p.Payee.String() + "](" + link("payee/"+p.Payee.String()) + ")")
	if p.Period < 86400 {
		b.WriteString(" (a test plan: the period is under a day)")
	}
	b.WriteString("\n\n")
	b.WriteString("Plan " + utoa(p.ID) + " · published " + formatTime(p.CreatedAt) + " · " + payingText(p, now) + " · " +
		plural(int(p.Pulls), "payment", "payments") + ", " + formatUgnot(p.Pulls*p.Amount) + " in total · last payment: " + formatTimeOrNever(p.LastPullAt) + "\n\n")
	b.WriteString("Plans never change. New terms are published as a new plan.\n\n")

	b.WriteString("## Supporters\n\n")
	list, next := payingFrom(p, from, now)
	if len(list) == 0 {
		b.WriteString("No paying supporters")
		if next >= 0 {
			b.WriteString(" in this part of the list")
		}
		b.WriteString(".\n\n")
	} else {
		b.WriteString("| Supporter | Since | Payments | Last payment |\n|---|---|---|---|\n")
		for _, m := range list {
			b.WriteString("| [" + short(m.Payer) + "](" + link("payer/"+m.Payer.String()) + ") | " + formatTime(m.CreatedAt) + " | " + itoa(m.Pulls) +
				" | " + formatTimeOrNever(m.lastPullAt()) + " |\n")
		}
		b.WriteString("\n")
	}
	if next >= 0 {
		b.WriteString("[More supporters](" + link("plan/"+utoa(id)) + "?from=" + strconv.Itoa(next) + ")\n\n")
	}
	unpaid, exact := countUnpaid(p, now)
	b.WriteString("Supporters are listed and counted from their first payment on, newest first, while their mandate is active. ")
	b.WriteString("Cancelled and expired mandates are not listed or counted; a supporter who revoked the session on chain stays listed until the mandate is cancelled or expires. ")
	b.WriteString(plural(unpaid, "active mandate has", "active mandates have") + " not paid yet (not listed)")
	if !exact {
		b.WriteString(", among the latest " + strconv.Itoa(ScanLimit))
	}
	b.WriteString(".\n\n")

	b.WriteString("## Support this plan\n\n")
	spend := p.Amount + FeeAllowance
	expires := now + 365*86400
	if pe == nil || pe.CollectorKey == "" {
		b.WriteString("The creator has not published a collector key yet, so there is nothing to subscribe to. Ask them to run `SetCollectorKey`.\n\n")
		return b.String()
	}
	if collectorFunded(pe.CollectorAddr) {
		b.WriteString("**New supporters cannot join right now.** The creator's collector key (`" + pe.CollectorAddr.String() + "`) has received coins, so its address is an account, and the chain refuses a session for a key whose address is an account. " +
			"This creator must publish a new collector key before new supporters can join. Existing mandates keep working until they expire; renewing needs the new key. " +
			"A creator can also hand you a fresh session key privately: `Subscribe` accepts any session key, not only the published one.\n\n")
		return b.String()
	}
	b.WriteString("You need [gnokey](https://docs.gno.land) and a key with some GNOT on " + ChainID + ". Replace `YOUR_KEY` with your key's name. " +
		"You can support one plan of each creator at a time: every plan of a creator is collected by the same key, and the chain allows one session per key. To switch plans, cancel and revoke first (time you paid for carries over to the same plan only). ")
	b.WriteString("These two commands give the creator's collector key (`" + pe.CollectorAddr.String() + "`) the right to take **at most " +
		formatUgnot(spend) + " every " + formatPeriod(p.Period) + "** (the price plus a fee allowance), through this realm only, for one year.\n\n")
	b.WriteString("1. Create the session (your own key; it cannot be done with a session). If the chain answers `session key address collides with existing account`, this collector key can no longer be used for new sessions: ask the creator to publish a new one.\n\n")
	b.WriteString("```\ngnokey maketx session create -pubkey " + pe.CollectorKey + " -allow-paths vm/exec:" + realmPath +
		" -spend-limit " + itoa(spend) + "ugnot -spend-period " + itoa(p.Period) + " -expires-at " + itoa(expires) + " " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
	b.WriteString("2. Record the terms here:\n\n")
	b.WriteString("```\ngnokey maketx call -pkgpath " + realmPath + " -func Subscribe -args " + utoa(p.ID) + " -args " + pe.CollectorAddr.String() +
		" -args " + itoa(expires) + " " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
	b.WriteString("The first payment is collected right after, then one every " + formatPeriod(p.Period) + ". If you paid for this plan before and that period has not ended " +
		"(you cancelled, the creator cancelled, or your mandate expired), the new mandate's first payment waits until it ends, so time you paid for is not charged twice. " +
		"The one exception: a wallet keeps paid time for at most " + strconv.Itoa(MaxCreditsPerPayer) + " plans it has left; beyond that, a creator's cancel keeps nothing for that creator's plan, and your own cancel or expiry lets the period that ends soonest go. Your page at `" + link("payer/<your address>") +
		"` shows how to stop.\n")
	return b.String()
}

func renderPayer(payer address, page int) string {
	var b strings.Builder
	b.WriteString("# Mandates of " + payer.String() + "\n\n")
	b.WriteString("Each mandate lets one creator's collector key pull a fixed amount once per period. To stop one completely, run both commands shown under it: ")
	b.WriteString("**revoke** removes the session on chain (no pull can be signed any more) and **cancel** ends the mandate here. Revoke alone already stops every payment.\n\n")
	list := MandatesOf(payer, page)
	if len(list) == 0 {
		b.WriteString("No mandates on this page.\n")
		return b.String()
	}
	now := time.Now().Unix()
	for _, m := range list {
		p := planOf(m.PlanID)
		b.WriteString("## Mandate " + utoa(m.ID) + ": [plan #" + utoa(p.ID) + " " + esc(p.Title) + "](" + link("plan/"+utoa(p.ID)) + ")\n\n")
		b.WriteString("- Status here: **" + m.Status + "**")
		if m.Status == "active" {
			b.WriteString(" (if you revoked the session on chain, no payment can be taken)")
		}
		b.WriteString("\n- Price: " + price(m.Amount, m.Period) + " to [" + short(m.Payee) + "](" + link("payee/"+m.Payee.String()) + ")\n")
		b.WriteString("- Session key: `" + m.Session.String() + "`\n")
		b.WriteString("- Payments: " + itoa(m.Pulls) + ", " + formatUgnot(m.Paid) + " in total, last: " + formatTimeOrNever(m.LastPullAt) + "\n")
		if m.Status == "active" {
			if m.Pulls == 0 && m.PaidThrough > 0 {
				b.WriteString("- First payment on " + formatTime(m.NextPullAt) + ": your current period is already paid (time carried over from your earlier mandate for this plan) · ends: " + formatTime(m.ExpiresAt) + "\n")
			} else {
				b.WriteString("- Next payment allowed from: " + formatTime(m.NextPullAt) + " · ends: " + formatTime(m.ExpiresAt) + "\n")
			}
		} else if m.PaidThrough > now {
			if PaidThrough(payer, m.PlanID) >= m.PaidThrough {
				b.WriteString("- Paid through " + formatTime(m.PaidThrough) + ": that time stays yours. A new mandate for this plan starts its payments then.\n")
			} else {
				b.WriteString("- Paid through " + formatTime(m.PaidThrough) + ", but that time could not be kept: a wallet keeps paid time for at most " +
					strconv.Itoa(MaxCreditsPerPayer) + " plans it has left, and a creator's cancel never pushes another one out. A new mandate for this plan would pay at once.\n")
			}
		}
		b.WriteString("\n")
		if m.Status != "cancelled" {
			b.WriteString("Revoke the session (your own key):\n\n")
			if m.SessionPubKey != "" {
				b.WriteString("```\ngnokey maketx session revoke -pubkey " + m.SessionPubKey + " " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
			} else {
				b.WriteString("This session's public key is not recorded here. List your sessions to find it, then run `gnokey maketx session revoke -pubkey <its gpub1 key> ... YOUR_KEY`:\n\n")
				b.WriteString("```\ngnokey query auth/accounts/" + payer.String() + "/sessions -remote " + Remote + "\n```\n\n")
			}
			b.WriteString("Cancel the mandate (your own key):\n\n")
			b.WriteString("```\ngnokey maketx call -pkgpath " + realmPath + " -func Cancel -args " + payer.String() + " -args " + m.Session.String() + " " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
		}
	}
	b.WriteString(pager("payer/"+payer.String(), page, len(list) == PageSize))
	return b.String()
}

func renderPayee(payee address, page int) string {
	var b strings.Builder
	b.WriteString("# Creator " + payee.String() + "\n\n")
	pe := payeeOf(payee)
	if pe == nil {
		b.WriteString("No plans from this address.\n")
		return b.String()
	}
	b.WriteString("| Plans | Payments | Received | Last payment |\n|---|---|---|---|\n")
	b.WriteString("| " + strconv.Itoa(pe.Plans) + " | " + itoa(pe.Pulls) + " | " + formatUgnot(pe.Paid) + " | " + formatTimeOrNever(pe.LastPullAt) + " |\n\n")
	if pe.CollectorKey == "" {
		b.WriteString("Collector key: **not published**. Supporters cannot subscribe until it is (see [help](" + link("help") + ")).\n\n")
	} else {
		b.WriteString("Collector key: `" + pe.CollectorAddr.String() + "` (`" + pe.CollectorKey + "`)\n\n")
		if collectorFunded(pe.CollectorAddr) {
			b.WriteString("**This collector key's address has received coins, so the chain refuses new sessions for it: nobody new can subscribe.** The creator must publish a new collector key; existing mandates keep being collected with this one until they expire, and renewing needs the new key.\n\n")
		}
	}
	b.WriteString("## Plans\n\n")
	list := PlansOf(payee, page)
	if len(list) == 0 {
		b.WriteString("No plans on this page.\n")
		return b.String()
	}
	b.WriteString("| Plan | Price | Payments this / last period | All payments | Last payment |\n|---|---|---|---|---|\n")
	for _, p := range list {
		b.WriteString("| [#" + utoa(p.ID) + " " + escCell(p.Title) + "](" + link("plan/"+utoa(p.ID)) + ") | " + price(p.Amount, p.Period) + " | " +
			infoPayingCell(p) + " | " + itoa(p.Pulls) + " | " + formatTimeOrNever(p.LastPullAt) + " |\n")
	}
	b.WriteString(pager("payee/"+payee.String(), page, len(list) == PageSize))
	return b.String()
}

func renderHelp() string {
	var b strings.Builder
	b.WriteString("# How to use Mandate\n\n")
	b.WriteString("Every command is for the **" + ChainID + "** test network and uses test GNOT. Replace the words in capitals. ")
	b.WriteString("Amounts are in ugnot (1 GNOT = 1,000,000 ugnot); periods and times are in seconds and unix seconds.\n\n")

	b.WriteString("## For creators\n\n")
	b.WriteString("1. Publish a plan with your own key: a title (one line, at most " + strconv.Itoa(MaxTitleLen) + " characters, no invisible formatting characters: direction controls and zero-width characters, the joiner included, are refused, so emoji joined into one, such as families, cannot be used), the amount (at least " +
		formatUgnot(MinAmount) + ") and the period (" + itoa(MinPeriod) + " seconds to " + itoa(MaxPeriod/86400) + " days). Plans cannot be changed.\n\n")
	b.WriteString("```\ngnokey maketx call -pkgpath " + realmPath + " -func Offer -args \"TITLE\" -args 1000000 -args 604800 " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
	b.WriteString("2. Make a separate key for collecting (`gnokey add COLLECTOR_KEY`) and publish its public key (the `gpub1...` value `gnokey list` shows), signed with your own key. " +
		"**Never send coins to the collector key's address**, not even for fees (the supporter pays every fee): an address that has received coins is an account, and the chain refuses to create a session for it, so nobody new could subscribe. " +
		"Anyone can do this to a published key with a 1 ugnot send, and a realm can even make the address an account that holds nothing. In most cases the plan page then says so; in every case supporters get the chain error `session key address collides with existing account` when they create the session, and the collector script warns. " +
		"Then the key can no longer be used for new sessions: make a new key and publish it (this command again). New supporters then use the new key, and existing mandates keep being collected with the old one: run one collector per key. " +
		"`Subscribe` accepts any session key you hand out, so you can also give supporters a fresh key privately:\n\n")
	b.WriteString("```\ngnokey maketx call -pkgpath " + realmPath + " -func SetCollectorKey -args GPUB_OF_COLLECTOR_KEY " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
	b.WriteString("3. Collect each payment when it is due, signed with the collector key on behalf of the supporter. Only the exact price is accepted, at most once per period. The fee counts against the supporter's fee allowance, so keep it small. " +
		"The command below uses today's minimum fee on " + ChainID + " (1 ugnot per 1,000 gas); when the chain raises its gas price, raise `-gas-fee` with it (`gnokey query auth/gasprice`), within the allowance. The collector script does this itself:\n\n")
	b.WriteString("```\ngnokey maketx call -pkgpath " + realmPath + " -func Pull -send AMOUNTugnot -master SUPPORTER_ADDRESS " + pullGas + " " + netFlags() + " COLLECTOR_KEY\n```\n\n")
	b.WriteString("The repository has a collector script that finds what is due through free queries and pulls it.\n\n")

	b.WriteString("## For supporters\n\n")
	b.WriteString("Open a plan's page: it shows the two exact commands, with the creator's collector key, the spend limit (price plus " + formatUgnot(FeeAllowance) +
		" for fees) and the period filled in. The general form:\n\n")
	b.WriteString("```\ngnokey maketx session create -pubkey COLLECTOR_GPUB -allow-paths vm/exec:" + realmPath + " -spend-limit PRICE_PLUS_" + itoa(FeeAllowance) +
		"ugnot -spend-period PERIOD_SECONDS -expires-at UNIX_TIME " + callGas + " " + netFlags() + " YOUR_KEY\n")
	b.WriteString("gnokey maketx call -pkgpath " + realmPath + " -func Subscribe -args PLAN_ID -args COLLECTOR_ADDRESS -args UNIX_TIME " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")
	b.WriteString("Use the same UNIX_TIME for both, at most " + itoa(MaxTerm/86400) + " days ahead. The session must allow exactly `vm/exec:" + realmPath +
		"` and nothing else, or Pull refuses it. PERIOD_SECONDS is the plan's period, at most " + itoa(MaxPeriod/86400) + " days (the chain's limit on a spend period). " +
		"You can support one plan of each creator at a time: all of a creator's plans are collected by one key, and the chain allows one session per key.\n\n")
	b.WriteString("### Stop a mandate\n\n")
	b.WriteString("Do both, with your own key. Your page (`" + link("payer/YOUR_ADDRESS") + "`) shows them filled in.\n\n")
	b.WriteString("```\ngnokey maketx session revoke -pubkey COLLECTOR_GPUB " + callGas + " " + netFlags() + " YOUR_KEY\n")
	b.WriteString("gnokey maketx call -pkgpath " + realmPath + " -func Cancel -args YOUR_ADDRESS -args COLLECTOR_ADDRESS " + callGas + " " + netFlags() + " YOUR_KEY\n```\n\n")

	b.WriteString("## Checking a supporter (free)\n\n")
	b.WriteString("To decide whether to deliver something to a supporter, ask how long their latest payment covers them: `PaidThrough` returns a unix time (0 if they never paid); deliver while now is before it. Paid time stays the supporter's after a cancel or an expiry. ")
	b.WriteString("Do not rely on a mandate merely existing: anyone can record one without paying. A realm cannot see a session revoked on chain either, but a revoked supporter stops paying, so `PaidThrough` stops moving and runs out within one period. It runs out at the due time and moves on only when the creator's collector takes the next payment, so allow a grace equal to how often the collector runs (an hour, say) before treating someone as lapsed. The second query shows the chain's view of the session.\n\n")
	b.WriteString("```\ngnokey query vm/qeval -data '" + realmPath + ".PaidThrough(address(\"PAYER\"), PLAN_ID)' -remote " + Remote + "\n")
	b.WriteString("gnokey query auth/accounts/PAYER/session/COLLECTOR_ADDRESS -remote " + Remote + "\n```\n\n")

	b.WriteString("## Rules the realm enforces\n\n")
	b.WriteString("- Pull: signed with a session key as a direct call; the session allows exactly this realm; a recorded, active mandate for that payer and key; exactly the price in ugnot; at most once per period (the next one is due one period after the last); not after the expiry.\n")
	b.WriteString("- Every other function refuses session keys and coins.\n")
	b.WriteString("- The first payment can be pulled as soon as the mandate is recorded (billing in advance). A missed period is never collected later.\n")
	b.WriteString("- A wallet can have at most " + strconv.Itoa(MaxSessionsPerWallet) + " sessions, so at most " + strconv.Itoa(MaxSessionsPerWallet) + " mandates at a time.\n")
	return b.String()
}

func renderNotFound() string {
	return "# Not found\n\nThere is no such page. [Back to Mandate](" + link("") + ")\n"
}

// payingText is the plan headline's count of payments per period. It
// counts payments, not distinct people: a creator paying its own plan from
// a second wallet counts too.
func payingText(p *Plan, now int64) string {
	current, previous := p.paidWindows(now)
	start := now / p.Period * p.Period
	return plural(current, "payment", "payments") + " in the current period (since " + formatTime(start) + "), " +
		strconv.Itoa(previous) + " in the one before"
}

// payingCell is the count in tables: paid this period / the one before.
func payingCell(p *Plan, now int64) string {
	current, previous := p.paidWindows(now)
	return strconv.Itoa(current) + " / " + strconv.Itoa(previous)
}

func infoPayingCell(p PlanInfo) string {
	return strconv.Itoa(p.PaidThisPeriod) + " / " + strconv.Itoa(p.PaidLastPeriod)
}

// intParam returns the integer value of key in the query, or def.
func intParam(query, key string, def int) int {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, key+"=") {
			n, err := strconv.Atoi(kv[len(key)+1:])
			if err == nil && n >= 0 && n <= 1_000_000_000 {
				return n
			}
		}
	}
	return def
}

// link returns the gnoweb link to a page of this realm.
func link(page string) string {
	p := strings.TrimPrefix(realmPath, "gno.land")
	if page == "" {
		return p
	}
	return p + ":" + page
}

func pager(page string, n int, more bool) string {
	s := ""
	if n > 1 {
		s += "[Previous page](" + link(page) + "?page=" + strconv.Itoa(n-1) + ") "
	}
	if more {
		s += "[Next page](" + link(page) + "?page=" + strconv.Itoa(n+1) + ")"
	}
	if s == "" {
		return ""
	}
	return s + "\n\n"
}

func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			n, err := strconv.Atoi(kv[5:])
			if err == nil && n >= 1 && n <= 1_000_000 {
				return n
			}
		}
	}
	return 1
}

func plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.Itoa(n) + " " + many
}

func netFlags() string {
	return "-broadcast -chainid " + ChainID + " -remote " + Remote
}

func price(amount, period int64) string {
	return formatUgnot(amount) + " every " + formatPeriod(period)
}

// formatUgnot shows an amount in GNOT with up to six decimals.
func formatUgnot(n int64) string {
	whole := n / 1_000_000
	frac := n % 1_000_000
	s := itoa(whole)
	if frac != 0 {
		f := strconv.FormatInt(frac+1_000_000, 10)[1:]
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

// formatPeriod shows a number of seconds in the largest exact unit.
func formatPeriod(sec int64) string {
	unit := func(n int64, one, many string) string {
		if n == 1 {
			return one
		}
		return itoa(n) + " " + many
	}
	switch {
	case sec%604800 == 0:
		return unit(sec/604800, "week", "weeks")
	case sec%86400 == 0:
		return unit(sec/86400, "day", "days")
	case sec%3600 == 0:
		return unit(sec/3600, "hour", "hours")
	case sec%60 == 0:
		return unit(sec/60, "minute", "minutes")
	}
	return unit(sec, "second", "seconds")
}

func formatTime(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04 UTC")
}

func formatTimeOrNever(unix int64) string {
	if unix == 0 {
		return "never"
	}
	return formatTime(unix)
}

func short(a address) string {
	s := a.String()
	if len(s) < 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package mandate

import (
	"chain"
	"strconv"
)

// fanout is the number of entries per chunk, and of chunks per super-chunk.
const fanout = 32

// fixedList is an append-only list of strings of one fixed width, in two
// levels of chunks. It holds values, never pointers to shared objects (on
// chain, rewriting an array costs about 0.37M gas for every pointer to a
// shared object it holds; docs/notes.md), and no array in it grows with the
// list's length except supers, by one entry per fanout*fanout appends:
//   - tail: the newest N % fanout entries, inside the owner object;
//   - when tail is full it becomes a chunk, appended to the last
//     super-chunk (at most fanout chunks each);
//   - supers: the list of super-chunks.
//
// So an append rewrites the owner and its tail; every fanout appends it also
// creates a chunk and rewrites one super-chunk (at most fanout pointers to
// objects that only it holds); every fanout*fanout appends it rewrites
// supers. set replaces an entry in place with one of the same width, so it
// never changes the storage size. Appends happen only in transactions signed
// with someone's own key (Subscribe, Offer), never under a session budget.
type fixedList struct {
	N      int
	tail   []string      // the newest N % fanout entries
	supers []*superChunk // full chunks, fanout per super-chunk, oldest first
}

type superChunk struct {
	chunks []*strChunk
}

type strChunk struct {
	items []string
}

func (l *fixedList) add(s string) {
	l.tail = append(l.tail, s)
	l.N++
	if len(l.tail) < fanout {
		return
	}
	c := &strChunk{items: l.tail}
	l.tail = nil
	if n := len(l.supers); n == 0 || len(l.supers[n-1].chunks) == fanout {
		l.supers = append(l.supers, &superChunk{chunks: []*strChunk{c}})
		return
	}
	sc := l.supers[len(l.supers)-1]
	sc.chunks = append(sc.chunks, c)
}

// at returns entry i (0 = oldest).
func (l *fixedList) at(i int) string {
	c := i / fanout
	if c < l.N/fanout {
		return l.supers[c/fanout].chunks[c%fanout].items[i%fanout]
	}
	return l.tail[i%fanout]
}

// set replaces entry i with s, which must have the same width.
func (l *fixedList) set(i int, s string) {
	c := i / fanout
	if c < l.N/fanout {
		l.supers[c/fanout].chunks[c%fanout].items[i%fanout] = s
		return
	}
	l.tail[i%fanout] = s
}

// Supporter entries: the payer's 40-character address, the mandate id
// padded to 10 digits, and one status character. Pull flips '0' to '1' at
// a mandate's first payment and Cancel sets 'x', both in place.
const (
	statusUnpaid    = '0'
	statusPaid      = '1'
	statusCancelled = 'x'
	entryWidth      = 40 + 10 + 1
)

// entry is a decoded supporter entry.
type entry struct {
	Payer  address
	ID     uint64 // mandate id
	Status byte
}

func encodeEntry(payer address, id uint64, status byte) string {
	return payer.String() + pad(id) + string(status)
}

func decodeEntry(s string) entry {
	id, _ := strconv.ParseUint(s[40:50], 10, 64)
	return entry{Payer: address(s[:40]), ID: id, Status: s[50]}
}

// setStatus rewrites the status character of entry i (same width).
func (l *fixedList) setStatus(i int, status byte) {
	s := l.at(i)
	l.set(i, s[:50]+string(status))
}

// activeMandate returns the mandate an entry names if it is still in its
// payer's active list (cancelled and replaced ones are not), or nil. It may
// have expired: callers check isActive.
func activeMandate(e entry) *Mandate {
	if pr := payerOf(e.Payer); pr != nil {
		for _, r := range pr.Active {
			if r.ID == e.ID {
				return r.M
			}
		}
	}
	return nil
}

// MaxActivePerPayer is how many active mandates one payer may hold: the
// chain allows 16 sessions per account (tm2 std.MaxSessionsPerAccount), and
// each active mandate needs its own session key.
const MaxActivePerPayer = MaxSessionsPerWallet

// Payer holds one payer's own lookups and nothing of anyone else's, so no
// address can make another payer's Pull, Subscribe or Cancel read or write
// more than the payer tree's depth.
//   - Active: the payer's current mandates, at most MaxActivePerPayer that
//     are not expired. Cancel removes an entry at once; an expired entry is
//     removed at the payer's next Subscribe. Each entry carries the session
//     address and plan id inline, so finding a mandate reads one small array
//     and loads only the mandate found.
//   - Head: the payer's newest mandate; older ones follow through
//     prevOfPayer (history, walked only by free reads).
//   - Credits: time the payer has paid for on a plan where they no longer
//     have an active mandate (cancelled by either side, or expired and
//     pruned), at most MaxCreditsPerPayer, each still in the future. A new
//     mandate for that plan starts when the credit ends, so paid time is
//     not lost or charged twice, unless 16 credits are already held (see
//     MaxCreditsPerPayer for who can then lose what).
type Payer struct {
	Active  []activeRef
	Head    *Mandate
	Credits []credit
}

// credit is paid time kept for a plan: the payer is covered until Until.
type credit struct {
	PlanID uint64
	Until  int64
}

// MaxCreditsPerPayer bounds a payer's kept credits: 16 plans left while
// each is still paid ahead. At the bound, the payer's own Cancel or expiry
// lets the credit ending soonest give way to a later one (that plan's time
// is lost); a payee's Cancel never evicts: its new credit is not kept.
const MaxCreditsPerPayer = 16

type activeRef struct {
	Session address
	PlanID  uint64
	ID      uint64 // mandate id, so a supporter entry resolves without loading mandates
	M       *Mandate
}

// payerOf returns a copy of the payer's record, or nil. Records are stored
// by value (no heap item, about 400 bytes less per payer); after changing
// one, write it back with save.
func payerOf(a address) *Payer {
	v := payers.Get(a.String())
	if v == nil {
		return nil
	}
	pr := v.(Payer)
	return &pr
}

func (pr *Payer) save(a address) { payers.Set(a.String(), *pr) }

// activeBySession returns the payer's active-list mandate for this session
// key (it may have expired but not been pruned yet), or nil.
func activeBySession(payer, sess address) *Mandate {
	if pr := payerOf(payer); pr != nil {
		for _, r := range pr.Active {
			if r.Session == sess {
				return r.M
			}
		}
	}
	return nil
}

// activeByPlan returns the payer's active-list mandate for the plan, or nil.
func activeByPlan(payer address, planID uint64) *Mandate {
	if pr := payerOf(payer); pr != nil {
		for _, r := range pr.Active {
			if r.PlanID == planID {
				return r.M
			}
		}
	}
	return nil
}

// removeActive drops m's entry from the payer's active list.
func (pr *Payer) removeActive(m *Mandate) {
	out := make([]activeRef, 0, len(pr.Active))
	for _, r := range pr.Active {
		if r.M != m {
			out = append(out, r)
		}
	}
	pr.Active = out
}

// pruneExpired drops expired entries from the active list (payer is the
// record's owner, for events). The paid time of an expired mandate for
// planID, the plan being subscribed to, is returned directly, so nothing in
// the same prune can evict it; every other expired mandate's paid time is
// kept as a credit for its plan.
func (pr *Payer) pruneExpired(payer address, planID uint64, now int64) int64 {
	keep := 0
	for _, r := range pr.Active {
		if r.M.isActive(now) {
			keep++
		}
	}
	if keep == len(pr.Active) {
		return 0
	}
	var own int64
	out := make([]activeRef, 0, keep)
	for _, r := range pr.Active {
		if r.M.isActive(now) {
			out = append(out, r)
			continue
		}
		var kept int64
		if r.PlanID == planID {
			if t := r.M.paidThrough(); t > now {
				own, kept = t, t
			}
		} else {
			kept = pr.keepCredit(payer, r.PlanID, r.M.paidThrough(), now, true)
		}
		chain.Emit("MandatePruned",
			"mandate", utoa(r.ID),
			"plan", utoa(r.PlanID),
			"payer", payer.String(),
			"kept", itoa(kept),
		)
	}
	pr.Active = out
	return own
}

// pruneCredits drops credits that have run out.
func (pr *Payer) pruneCredits(now int64) {
	keep := 0
	for _, c := range pr.Credits {
		if c.Until > now {
			keep++
		}
	}
	if keep == len(pr.Credits) {
		return
	}
	out := make([]credit, 0, keep)
	for _, c := range pr.Credits {
		if c.Until > now {
			out = append(out, c)
		}
	}
	pr.Credits = out
}

// keepCredit records that the payer is paid on the plan until `until`
// (nothing if that is not in the future). One credit per plan, the later
// time wins. At MaxCreditsPerPayer: with evict (the payer's own Cancel, or
// the expiry prune at the payer's own Subscribe), the credit ending soonest
// gives way if this one ends later; without evict (a payee's Cancel), this
// one is not kept, so no third party can remove a credit the payer holds.
//
// It returns the time kept (0 if none) and emits CreditDropped for a credit
// it pushes out.
func (pr *Payer) keepCredit(payer address, planID uint64, until, now int64, evict bool) int64 {
	if until <= now {
		return 0
	}
	pr.pruneCredits(now)
	// A plan has a credit only while the payer has no active mandate for it
	// (Subscribe uses it up), so this is a guard, not a path taken today.
	for i := range pr.Credits {
		if pr.Credits[i].PlanID == planID {
			if until > pr.Credits[i].Until {
				pr.Credits[i] = credit{PlanID: planID, Until: until}
			}
			return pr.Credits[i].Until
		}
	}
	if len(pr.Credits) < MaxCreditsPerPayer {
		pr.Credits = append(pr.Credits, credit{PlanID: planID, Until: until})
		return until
	}
	if !evict {
		return 0
	}
	soonest := 0
	for i := range pr.Credits {
		if pr.Credits[i].Until < pr.Credits[soonest].Until {
			soonest = i
		}
	}
	if until <= pr.Credits[soonest].Until {
		return 0
	}
	chain.Emit("CreditDropped",
		"payer", payer.String(),
		"plan", utoa(pr.Credits[soonest].PlanID),
		"until", itoa(pr.Credits[soonest].Until),
	)
	pr.Credits[soonest] = credit{PlanID: planID, Until: until}
	return until
}

// creditFor returns until when a kept credit covers the payer on the plan,
// or 0. For reads; it changes nothing.
func (pr *Payer) creditFor(planID uint64, now int64) int64 {
	for _, c := range pr.Credits {
		if c.PlanID == planID && c.Until > now {
			return c.Until
		}
	}
	return 0
}

// takeCredit removes the plan's credit and returns until when it covered
// the payer, or 0 if there was none still in the future.
func (pr *Payer) takeCredit(planID uint64, now int64) int64 {
	pr.pruneCredits(now)
	for i, c := range pr.Credits {
		if c.PlanID == planID {
			out := make([]credit, 0, len(pr.Credits)-1)
			out = append(out, pr.Credits[:i]...)
			pr.Credits = append(out, pr.Credits[i+1:]...)
			return c.Until
		}
	}
	return 0
}

// latestBySession returns the payer's newest mandate for this session key,
// active or not, walking the history when it is no longer active. For free
// reads only.
func latestBySession(payer, sess address) *Mandate {
	if m := activeBySession(payer, sess); m != nil {
		return m
	}
	if pr := payerOf(payer); pr != nil {
		for m := pr.Head; m != nil; m = m.prevOfPayer {
			if m.Session == sess {
				return m
			}
		}
	}
	return nil
}

// payerHead returns the payer's newest mandate.
func payerHead(payer address) *Mandate {
	if pr := payerOf(payer); pr != nil {
		return pr.Head
	}
	return nil
}

package mandate

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// fixedList keeps the newest entries in tail, full chunks of fanout, and
// fanout chunks per super-chunk; every index maps to the right entry across
// the boundaries, and set rewrites in place.
func TestFixedList(t *testing.T) {
	var l fixedList
	n := fanout*fanout + 3*fanout + 5 // past the first super-chunk
	for i := 0; i < n; i++ {
		l.add(encodeEntry(payer, uint64(i), statusUnpaid))
		uassert.Equal(t, i+1, l.N)
		for _, j := range []int{0, i / 2, i} {
			uassert.Equal(t, uint64(j), decodeEntry(l.at(j)).ID)
		}
		uassert.Equal(t, (i+1)%fanout, len(l.tail))
		full := (i + 1) / fanout
		uassert.Equal(t, (full+fanout-1)/fanout, len(l.supers))
	}
	uassert.Equal(t, fanout, len(l.supers[0].chunks))
	uassert.Equal(t, 3, len(l.supers[1].chunks))
	for _, j := range []int{0, 31, 32, 33, fanout*fanout - 1, fanout * fanout, n - 1} {
		l.setStatus(j, statusPaid)
		e := decodeEntry(l.at(j))
		uassert.Equal(t, uint64(j), e.ID)
		uassert.True(t, e.Status == statusPaid)
		uassert.Equal(t, entryWidth, len(l.at(j)))
		uassert.Equal(t, payer.String(), e.Payer.String())
	}
	// No preallocation: a slot costs storage even when empty.
	var small fixedList
	small.add("x")
	uassert.Equal(t, 1, cap(small.tail))
}

// Supporter lists keep their order across chunks.
func TestLongLists(cur realm, t *testing.T) {
	resetState()
	pid := offer(cur, payee, "Plan", gnot, day)
	n := 2*fanout + 3
	for i := 0; i < n; i++ {
		subscribe(cur, testutils.TestAddress("md_l"+itoa(int64(i))), pid, sessA, now()+day)
	}
	uassert.Equal(t, n, planOf(pid).Supporters.N)
	seen := 0
	for page := 1; ; page++ {
		list := SupportersOf(pid, page)
		for _, m := range list {
			uassert.Equal(t, uint64(seen+1), m.ID)
			uassert.Equal(t, testutils.TestAddress("md_l"+itoa(int64(seen))).String(), m.Payer.String())
			seen++
		}
		if len(list) < PageSize {
			break
		}
	}
	uassert.Equal(t, n, seen)
}

// A payer's history is newest first and paged; lookups by session and by
// plan return the latest mandate.
func TestPayerHistory(cur realm, t *testing.T) {
	resetState()
	pid := offer(cur, payee, "Plan", gnot, day)
	pid2 := offer(cur, payee, "Plan 2", gnot, day)
	var ids []uint64
	for i := 0; i < 25; i++ {
		ids = append(ids, subscribe(cur, payer, pid, sessA, now()+day))
		cancel(cur, payer, payer, sessA)
	}
	last := subscribe(cur, payer, pid2, sessA, now()+day)
	p1 := MandatesOf(payer, 1)
	p2 := MandatesOf(payer, 2)
	uassert.Equal(t, PageSize, len(p1))
	uassert.Equal(t, 6, len(p2))
	uassert.Equal(t, 0, len(MandatesOf(payer, 3)))
	uassert.Equal(t, last, p1[0].ID)
	uassert.Equal(t, ids[24], p1[1].ID)
	uassert.Equal(t, ids[0], p2[5].ID)
	m, _ := MandateOf(payer, sessA)
	uassert.Equal(t, last, m.ID)
	uassert.True(t, HasMandate(payer, pid2))
	uassert.False(t, HasMandate(payer, pid))
	pl, _ := GetPlan(pid)
	uassert.Equal(t, 25, pl.Mandates)
	uassert.Equal(t, 25, pl.Cancelled)
	// The payer page pages the same way.
